=== extract/extract.py
import sys, os, re, UnityPy
root = sys.argv[1]
SA = "C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend/WizardOfLegend_Data/StreamingAssets"
out = os.path.join(root, "data")
n = 0
rows = []
def safe(p):
    p = p.replace("\\", "/")
    p = re.sub(r'[<>:"|?*]', "_", p).lstrip("/")
    return p
for b in sys.argv[2:]:
    env = UnityPy.load(os.path.join(SA, b))
    cont = {}
    for path, obj in env.container.items():
        cont[obj.path_id] = path
    for obj in env.objects:
        if obj.type.name != "TextAsset":
            continue
        try:
            d = obj.read()
            name = d.m_Name
            data = d.m_Script
            if isinstance(data, str):
                data = data.encode("utf-8", "surrogateescape")
            else:
                data = bytes(data)
            p = cont.get(obj.path_id)
            if not p:
                p = "_noncontainer/%s/%s_%d.txt" % (b, name, obj.path_id)
            p = safe(p)
            fp = os.path.join(out, p)
            if os.path.exists(fp):
                fp = fp + "." + b + "_%d" % obj.path_id
            os.makedirs(os.path.dirname(fp), exist_ok=True)
            with open(fp, "wb") as f:
                f.write(data)
            n += 1
            rows.append((os.path.relpath(fp, out).replace("\\", "/"), len(data), b))
        except Exception as e:
            print("ERR", b, obj.path_id, e)
with open(os.path.join(root, "filelist.txt"), "w", encoding="utf-8") as f:
    for r in sorted(rows):
        f.write("%s\t%d\t%s\n" % r)
print("TextAssets:", n)
=== extract/prefabs.py
"""Dump MonoBehaviour serialized fields of Enemy/Boss/Player prefabs. Usage: prefabs.py <root>"""
import sys, os, re, json, csv, UnityPy
root = sys.argv[1]
SA = "C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend/WizardOfLegend_Data/StreamingAssets/core"
OUT = os.path.join(root, "data", "prefabs")
os.makedirs(OUT, exist_ok=True)
KEYS = ("/prefabs/enemies/", "/prefabs/bosses/", "/prefabs/player")
SKIP = {"m_GameObject", "m_Enabled", "m_Script", "m_Name", "lastAttack", "currentSurroundPoint",
        "myOrigin", "originalRotation", "originalScale"}

def is_pptr(v):
    return isinstance(v, dict) and "m_PathID" in v and "m_FileID" in v

def clean(v):
    if is_pptr(v):
        return None
    if isinstance(v, dict):
        if "_baseValue" in v and "_currentValue" in v:
            return v["_baseValue"]
        d = {}
        for k, x in v.items():
            if k in SKIP: continue
            c = clean(x)
            if c is not None and c != {} and c != []:
                d[k] = c
        return d
    if isinstance(v, list):
        l = [clean(x) for x in v]
        return [x for x in l if x is not None and x != {}]
    return v

env = UnityPy.load(SA)
by_pid = {}
paths = {}
for p, o in env.container.items():
    pl = "/" + p.lower()
    if p.endswith(".prefab") and any(k in pl for k in KEYS):
        paths[p] = o

def collect(go, prefix, out, depth=0):
    gname = go.m_Name
    for c in go.m_Components:
        try:
            comp = c.component.read() if hasattr(c, "component") else c.read()
        except Exception as e:
            out.append({"go": prefix + gname, "error": str(e)}); continue
        if comp.object_reader.type.name != "MonoBehaviour":
            continue
        try:
            cls = comp.m_Script.read().m_ClassName
            t = comp.object_reader.read_typetree()
            out.append({"go": prefix + gname, "class": cls, "fields": clean(t)})
        except Exception as e:
            out.append({"go": prefix + gname, "error": "%s: %s" % (type(e).__name__, e)})
    # children
    try:
        tr = go.m_Transform.read() if hasattr(go, "m_Transform") else None
        if tr is None:
            for c in go.m_Components:
                x = c.component.read() if hasattr(c, "component") else c.read()
                if x.object_reader.type.name in ("Transform", "RectTransform"):
                    tr = x; break
        for ch in tr.m_Children:
            cg = ch.read().m_GameObject.read()
            collect(cg, prefix + gname + "/", out, depth + 1)
    except Exception as e:
        out.append({"go": prefix + gname, "error": "children: %s" % e})

def first(comps, cls, key):
    for c in comps:
        if c.get("class") == cls or (cls == "*" and "fields" in c):
            f = c.get("fields", {})
            if key in f: return f[key]
    return ""

rows = []
fail = 0
for p, o in sorted(paths.items()):
    name = os.path.splitext(os.path.basename(p))[0]
    try:
        go = o.read()
        comps = []
        collect(go, "", comps)
        sub = "playerskills" if "/playerskills/" in p else "player" if "/player/" in p else ("bosses" if "/bosses/" in p else "enemies")
        d = {"path": p, "kind": sub, "components": comps}
        with open(os.path.join(OUT, name + ".json"), "w", encoding="utf-8") as f:
            json.dump(d, f, indent=1, ensure_ascii=False)
        errs = [c for c in comps if "error" in c]
        if errs: print("PARTIAL", name, errs[:2])
        # summary
        r = {"name": name, "kind": sub}
        for cls, key, col in [("Health", "healthStat", "maxHealth"), ("Health", "armorStat", "armor"),
                              ("Health", "evadeStat", "evade"), ("Health", "damageTakenStat", "damageTaken")]:
            r[col] = first(comps, cls, key)
        mv = [c for c in comps if c.get("class") == "Movement"]
        for k in ("moveSpeedStat", "dashSpeedStat", "dashDurationStat"):
            for c in mv:
                if k in c["fields"]: r[k] = c["fields"][k]; break
        for k in ("hitStunDurationModifier", "alertRadius", "escapeRadius", "attackRadius", "surroundRadius", "alertNearbyEnemiesRadius", "maxAlertDistance", "element"):
            r[k] = first(comps, "*", k)
        # other numeric: min windup/exit/cooldown found anywhere
        wu, ex, cd = [], [], []
        def walk(v, key=""):
            if isinstance(v, dict):
                for k, x in v.items(): walk(x, k)
            elif isinstance(v, list):
                for x in v: walk(x, key)
            elif isinstance(v, (int, float)) and not isinstance(v, bool):
                kl = key.lower()
                if "windup" in kl and "id" not in kl and v > 0: wu.append(v)
                elif "exittime" in kl and v > 0: ex.append(v)
                elif "cooldown" in kl and v > 0: cd.append(v)
        for c in comps:
            if "fields" in c: walk(c["fields"])
        r["windupTimes"] = ";".join(str(round(x, 3)) for x in wu[:8])
        r["exitTimes"] = ";".join(str(round(x, 3)) for x in ex[:8])
        r["cooldowns"] = ";".join(str(round(x, 3)) for x in cd[:8])
        r["classes"] = ";".join(sorted({c["class"] for c in comps if "class" in c and c["class"] not in ("Health", "Movement", "SortSpriteLayer", "Fall", "MecanimEvents")}))
        rows.append(r)
    except Exception as e:
        fail += 1
        print("FAIL", name, type(e).__name__, e)
cols = []
for r in rows:
    for k in r:
        if k not in cols: cols.append(k)
with open(os.path.join(OUT, "summary.csv"), "w", newline="", encoding="utf-8") as f:
    w = csv.DictWriter(f, fieldnames=cols); w.writeheader(); w.writerows(rows)
print("dumped", len(rows), "failed", fail)
=== extract2/dump_all.py
"""dump_all.py <out.jsonl>: every prefab in core, all components (typetree), pptr resolved to names. One JSON per line."""
import UnityPy, json, sys, os
SA="C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend/WizardOfLegend_Data/StreamingAssets/core"
env=UnityPy.load(SA)
objs={o.path_id:o for o in env.objects}
cont={o.path_id:p for p,o in env.container.items()}
namecache={}
def pname(pid):
    if pid in namecache: return namecache[pid]
    o=objs.get(pid); r=None
    if o is None: r="?ext"
    elif pid in cont: r=cont[pid]
    else:
        try:
            tt=o.type.name
            if tt=="GameObject": r="GO:"+o.read_typetree()["m_Name"]
            elif tt in ("AnimatorController","AnimationClip","Sprite","Material","PhysicsMaterial2D","Texture2D","TextAsset"): r=tt+":"+o.read_typetree().get("m_Name","")
            elif tt=="MonoBehaviour":
                t=o.read_typetree(); go=objs.get(t["m_GameObject"]["m_PathID"])
                r="MB:"+(go.read_typetree()["m_Name"] if go else "?")
            else: r=tt
        except Exception as e: r="err"
    namecache[pid]=r; return r
SKIPT={"SpriteRenderer","ParticleSystem","ParticleSystemRenderer","CanvasRenderer","Light","LineRenderer","TrailRenderer","Canvas","FlareLayer","GUILayer","AudioListener","AudioHighPassFilter"}
SKIPK={"m_GameObject","m_Enabled","m_Script","m_ObjectHideFlags","m_CorrespondingSourceObject","m_PrefabInstance","m_PrefabAsset","m_EditorHideFlags","m_EditorClassIdentifier","m_Name"}
def clean(v):
    if isinstance(v,dict):
        if set(v)=={"m_FileID","m_PathID"}: 
            return None if v["m_PathID"]==0 else {"ref":pname(v["m_PathID"])}
        if "_baseValue" in v and "_currentValue" in v: return v["_baseValue"]
        d={}
        for k,x in v.items():
            if k in SKIPK: continue
            c=clean(x)
            if c is not None and c!={} and c!=[]: d[k]=c
        return d
    if isinstance(v,list):
        l=[clean(x) for x in v]; return [x for x in l if x is not None and x!={}]
    return v
def walk(goobj,prefix,out,parent_scale):
    t=goobj.read_typetree(); gname=t["m_Name"]; comps=[]
    scale=list(parent_scale); pos=None; lscale=None; children=[]
    for c in t["m_Component"]:
        pid=c["component"]["m_PathID"]; o=objs.get(pid)
        if o is None: continue
        tn=o.type.name
        if tn in("Transform","RectTransform"):
            tt=o.read_typetree(); ls=tt["m_LocalScale"]; lscale=[ls["x"],ls["y"],ls["z"]]
            scale=[parent_scale[i]*lscale[i] for i in range(3)]
            p=tt["m_LocalPosition"]; pos=[p["x"],p["y"],p["z"]]
            children=[ch["m_PathID"] for ch in tt["m_Children"]]
            continue
        if tn in SKIPT: continue
        try:
            tt=o.read_typetree()
            if tn=="MonoBehaviour":
                cls=objs[tt["m_Script"]["m_PathID"]].read_typetree()["m_ClassName"] if tt["m_Script"]["m_PathID"] in objs else "?"
            else: cls=tn
            en=tt.get("m_Enabled",1)
            comps.append({"class":cls,"enabled":en,"fields":clean(tt)})
        except Exception as e:
            comps.append({"class":tn,"error":str(e)})
    out.append({"go":prefix+gname,"active":t.get("m_IsActive",1),"layer":t.get("m_Layer"),"tag":t.get("m_Tag"),"localPos":pos,"localScale":lscale,"worldScale":scale,"components":comps})
    for cp in children:
        try:
            cg=objs[objs[cp].read_typetree()["m_GameObject"]["m_PathID"]]
            walk(cg,prefix+gname+"/",out,scale)
        except Exception as e: out.append({"go":prefix+gname+"/?","error":str(e)})
n=0
with open(sys.argv[1],"w",encoding="utf-8") as f:
    for p,o in sorted(env.container.items(),key=lambda x:x[0]):
        if not p.endswith(".prefab"): continue
        try:
            out=[]; walk(objs[o.path_id],"",out,[1,1,1])
            f.write(json.dumps({"path":p,"objects":out},ensure_ascii=False)+"\n"); n+=1
        except Exception as e: print("FAIL",p,e)
print("prefabs",n)
=== extract2/anim_clips.py
"""Usage: anim_clips.py <outdir>. Writes anim_clips.csv, anim_events.csv, anim_transitions.csv"""
import UnityPy, json, csv, os, sys, collections
OUT = sys.argv[1]; os.makedirs(OUT, exist_ok=True)
SA="C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend/WizardOfLegend_Data/StreamingAssets/core"
env=UnityPy.load(SA)
objs={o.path_id:o for o in env.objects}
cont_by_pid={o.path_id:p for p,o in env.container.items()}

# --- owners: Animator -> root prefab path
ctrl_owners=collections.defaultdict(set)
def root_of(go):
    # walk transform parents
    seen=0
    cur=go
    while seen<40:
        tr=None
        for c in cur.m_Components:
            x=c.component.read() if hasattr(c,"component") else c.read()
            if x.object_reader.type.name in("Transform","RectTransform"): tr=x;break
        if tr is None or tr.m_Father.path_id==0: return cur
        cur=tr.m_Father.read().m_GameObject.read(); seen+=1
    return cur
for o in env.objects:
    if o.type.name!="Animator": continue
    try:
        t=o.read_typetree()
        cp=t["m_Controller"]["m_PathID"]
        if not cp: continue
        go=o.read().m_GameObject.read()
        r=root_of(go)
        pp=cont_by_pid.get(r.object_reader.path_id) or ("(noncontainer root %s)"%r.m_Name)
        ctrl_owners[cp].add(pp)
    except Exception as e:
        print("animator err",o.path_id,e)

clip_rows=[];ev_rows=[];tr_rows=[];seen_clips={}
clipinfo={}
def clip_info(pid):
    if pid in clipinfo: return clipinfo[pid]
    o=objs.get(pid)
    if o is None or o.type.name!="AnimationClip": clipinfo[pid]=None; return None
    t=o.read_typetree(); mc=t["m_MuscleClip"]
    d={"name":t["m_Name"],"len":mc["m_StopTime"]-mc["m_StartTime"],"fps":t["m_SampleRate"],"loop":bool(mc["m_LoopTime"]),
       "events":[(e["time"],e["functionName"],e["data"],e["floatParameter"],e["intParameter"]) for e in t.get("m_Events",[])],"path":cont_by_pid.get(pid,"")}
    clipinfo[pid]=d; return d

for o in env.objects:
    if o.type.name!="AnimatorController": continue
    t=o.read_typetree()
    cpath=cont_by_pid.get(o.path_id,"(noncontainer)")
    cname=t["m_Name"]
    tos=dict(t["m_TOS"])
    clips=[c["m_PathID"] for c in t["m_AnimationClips"]]
