"""Общие хелперы: пути, логирование, чистка typetree, кривые, пакеты."""
import json
import math
import os
import re
import sys
import time

TOOL_VERSION = "1.0"


def log(msg, *a):
    t = time.strftime("%H:%M:%S")
    try:
        sys.stderr.write("[%s] %s\n" % (t, (msg % a) if a else msg))
        sys.stderr.flush()
    except Exception:
        pass


def safe_rel(p):
    """Контейнерный путь -> безопасный относительный путь файловой системы."""
    p = p.replace("\\", "/")
    p = re.sub(r'[<>:"|?*\x00-\x1f]', "_", p)
    parts = [x for x in p.split("/") if x not in ("", ".", "..")]
    return "/".join(x.rstrip(". ") or "_" for x in parts)


def json_dump(obj, path, indent=1):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        json.dump(obj, f, indent=indent, ensure_ascii=False, allow_nan=False, default=str)


def fnum(x):
    """float без nan/inf (JSON-безопасно)."""
    if isinstance(x, float) and not math.isfinite(x):
        return "nan" if x != x else ("inf" if x > 0 else "-inf")
    return x


# ---------- typetree cleaning ----------

SKIP_KEYS = {"m_GameObject", "m_Enabled", "m_Script", "m_ObjectHideFlags", "m_CorrespondingSourceObject",
             "m_PrefabInstance", "m_PrefabAsset", "m_PrefabInternal", "m_EditorHideFlags", "m_EditorClassIdentifier",
             "m_Name", "m_PrefabParentObject"}
SKIP_CLASSES = {"SpriteRenderer", "ParticleSystem", "ParticleSystemRenderer", "CanvasRenderer", "Canvas",
                "FlareLayer", "GUILayer", "AudioListener", "AudioHighPassFilter", "MeshRenderer",
                "SkinnedMeshRenderer", "LineRenderer", "TrailRenderer"}

_BASE_RX = re.compile(r"^_?(m_)?base(value)?$", re.I)
_CUR_RX = re.compile(r"^_?(m_)?(current|cur)(value)?$", re.I)


def is_pptr(v):
    return isinstance(v, dict) and set(v) == {"m_FileID", "m_PathID"}


def is_curve(v):
    return isinstance(v, dict) and isinstance(v.get("m_Curve"), list) and "m_PreInfinity" in v


def stat_base(v):
    """Stat-обёртка вида {_baseValue,_currentValue,...} -> (True, base). Универсально по именам."""
    if not isinstance(v, dict) or len(v) > 8:
        return False, None
    b = [k for k in v if _BASE_RX.match(k)]
    c = [k for k in v if _CUR_RX.match(k)]
    if len(b) == 1 and len(c) == 1:
        return True, v[b[0]]
    return False, None


def compact_curve(v):
    keys = []
    for k in v["m_Curve"]:
        row = []
        for n in ("time", "value", "inSlope", "outSlope"):
            x = k.get(n)
            if isinstance(x, dict):
                x = [fnum(round(y, 6)) if isinstance(y, float) else y for y in x.values()]
            elif isinstance(x, float):
                x = fnum(round(x, 6))
            row.append(x)
        keys.append(row)
    return {"keys": keys, "pre": v.get("m_PreInfinity"), "post": v.get("m_PostInfinity")}


class Cleaner:
    """clean(): убирает ссылки на мусор, сворачивает Stat-обёртки, резолвит PPtr в имена,
    вытаскивает AnimationCurve в collector."""

    def __init__(self, ref_namer):
        self.ref_namer = ref_namer
        self.curves = None  # список, если собираем

    def clean(self, v, path=""):
        if isinstance(v, dict):
            if is_pptr(v):
                if v["m_PathID"] == 0:
                    return None
                return {"ref": self.ref_namer(v["m_FileID"], v["m_PathID"])}
            if is_curve(v):
                cc = compact_curve(v)
                if self.curves is not None:
                    self.curves.append((path, cc))
                return {"curve": cc["keys"], "pre": cc["pre"], "post": cc["post"]}
            ok, base = stat_base(v)
            if ok:
                return self.clean(base, path) if isinstance(base, (dict, list)) else fnum(base)
            d = {}
            for k, x in v.items():
                if k in SKIP_KEYS:
                    continue
                c = self.clean(x, path + "." + k if path else k)
                if c is not None and c != {} and c != []:
                    d[k] = c
            return d
        if isinstance(v, list):
            out = []
            for i, x in enumerate(v):
                c = self.clean(x, "%s[%d]" % (path, i))
                if c is not None and c != {}:
                    out.append(c)
            return out
        if isinstance(v, (bytes, bytearray)):
            return "<bytes %d>" % len(v)
        return fnum(v)


def merge_stats(a, b):
    """Рекурсивное слияние счётчиков: числа суммируются, max_*/min_* — max/min."""
    for k, v in b.items():
        if isinstance(v, dict):
            merge_stats(a.setdefault(k, {}), v)
        elif isinstance(v, (int, float)):
            if k.startswith("max_"):
                a[k] = max(a.get(k, v), v)
            elif k.startswith("min_"):
                a[k] = min(a.get(k, v), v)
            else:
                a[k] = a.get(k, 0) + v
        else:
            a.setdefault(k, v)
    return a


def folder_of(path, depth):
    parts = path.split("/")[:-1]
    return "/".join(parts[:depth]) if parts else "(root)"


def category_of(path):
    m = re.search(r"(?:^|/)prefabs/([^/]+)/", path)
    if m:
        return m.group(1)
    parts = path.split("/")
    return parts[-2] if len(parts) > 1 else "(root)"

