"""Детект Unity-игры: версия, бэкенд, расположение ассетов. Только чтение, ничего не меняет."""
import os
import re

BUNDLE_MAGIC = (b"UnityFS", b"UnityWeb", b"UnityRaw", b"UnityArchive")
VER_RX = re.compile(rb"\d{1,4}\.\d{1,2}\.\d{1,2}[abfpc]\d{1,3}")
SERIAL_NAME_RX = re.compile(r"^(level\d+|globalgamemanagers(\.assets)?|resources\.assets|sharedassets\d+\.assets|mainData|[^/\\]+\.assets)$")
SKIP_EXT = (".manifest", ".ress", ".resource", ".json", ".hash", ".txt", ".xml", ".meta", ".dll", ".exe")


def find_data_dir(game_dir):
    g = os.path.abspath(game_dir)
    if g.endswith("_Data") and os.path.isdir(g):
        return os.path.dirname(g), g
    cands = [os.path.join(g, d) for d in sorted(os.listdir(g)) if d.endswith("_Data") and os.path.isdir(os.path.join(g, d))]
    # macOS: Game.app/Contents/Resources/Data
    mac = os.path.join(g, "Contents", "Resources", "Data")
    if not cands and os.path.isdir(mac):
        return g, mac
    for c in cands:
        if os.path.exists(os.path.join(c, "globalgamemanagers")) or os.path.exists(os.path.join(c, "data.unity3d")) \
                or os.path.exists(os.path.join(c, "mainData")):
            return g, c
    if cands:
        return g, cands[0]
    raise SystemExit("Не найден каталог *_Data в %s - это точно папка Unity-игры?" % g)


def sniff_magic(path):
    try:
        with open(path, "rb") as f:
            head = f.read(16)
    except OSError:
        return None
    for m in BUNDLE_MAGIC:
        if head.startswith(m):
            return m.decode()
    return None


def read_unity_version(data_dir):
    """Версия движка: из globalgamemanagers / data.unity3d / mainData (в заголовке лежит строка версии)."""
    for name in ("globalgamemanagers", "mainData", "data.unity3d"):
        p = os.path.join(data_dir, name)
        if os.path.exists(p):
            with open(p, "rb") as f:
                head = f.read(4096)
            m = VER_RX.search(head)
            if m:
                return m.group(0).decode()
    # fallback: любой бандл в StreamingAssets
    sa = os.path.join(data_dir, "StreamingAssets")
    for root, _, files in os.walk(sa):
        for fn in files:
            p = os.path.join(root, fn)
            if sniff_magic(p):
                with open(p, "rb") as f:
                    m = VER_RX.search(f.read(512))
                if m:
                    return m.group(0).decode()
    return None


def detect(game_dir):
    root, data = find_data_dir(game_dir)
    info = {"game_root": root, "data_dir": data, "game_name": os.path.basename(data)[:-5] if data.endswith("_Data") else os.path.basename(root)}
    info["unity_version"] = read_unity_version(data)
    managed = os.path.join(data, "Managed")
    asm = os.path.join(managed, "Assembly-CSharp.dll")
    meta = None
    for dp, _, fns in os.walk(data):
        if "global-metadata.dat" in fns:
            meta = os.path.join(dp, "global-metadata.dat")
            break
        # не уходим в StreamingAssets, там много файлов
        if dp.endswith("StreamingAssets"):
            _[:] = []
    ga = os.path.join(root, "GameAssembly.dll")
    if os.path.exists(ga) or meta:
        info["backend"] = "il2cpp"
        info["game_assembly"] = ga if os.path.exists(ga) else None
        info["global_metadata"] = meta
    elif os.path.exists(asm):
        info["backend"] = "mono"
    else:
        info["backend"] = "unknown"
    info["assembly_csharp"] = asm if os.path.exists(asm) else None
    info["managed_dir"] = managed if os.path.isdir(managed) else None
    info["assembly_csharp_firstpass"] = os.path.join(managed, "Assembly-CSharp-firstpass.dll") \
        if os.path.exists(os.path.join(managed, "Assembly-CSharp-firstpass.dll")) else None

    units = []  # {path, kind: bundle|assets|scene, size}

    def add(p, kind):
        units.append({"path": p, "kind": kind, "size": os.path.getsize(p), "rel": os.path.relpath(p, data).replace("\\", "/")})

    # сериализованные файлы в корне *_Data
    for fn in sorted(os.listdir(data)):
        p = os.path.join(data, fn)
        if not os.path.isfile(p) or fn.lower().endswith(SKIP_EXT):
            continue
        magic = sniff_magic(p)
        if magic:
            add(p, "bundle")
        elif re.match(r"^level\d+$", fn):
            add(p, "scene")
        elif SERIAL_NAME_RX.match(fn):
            add(p, "assets")
    # бандлы: StreamingAssets (включая aa/ Addressables) и прочие подкаталоги *_Data (кроме Managed/Mono/Plugins)
    for sub in sorted(os.listdir(data)):
        sp = os.path.join(data, sub)
        if not os.path.isdir(sp) or sub in ("Managed", "Mono", "MonoBleedingEdge", "Plugins", "il2cpp_data", "Resources"):
            continue
        for dp, _, fns in os.walk(sp):
            for fn in sorted(fns):
                p = os.path.join(dp, fn)
                if fn.lower().endswith(SKIP_EXT):
                    continue
                if os.path.getsize(p) < 64:
                    continue
                if sniff_magic(p):
                    add(p, "bundle")
    info["units"] = units
    info["streaming_assets"] = os.path.isdir(os.path.join(data, "StreamingAssets"))
    info["has_resources_assets"] = os.path.exists(os.path.join(data, "resources.assets"))
    info["n_levels"] = sum(1 for u in units if u["kind"] == "scene")
    info["n_bundles"] = sum(1 for u in units if u["kind"] == "bundle")
    info["n_assets_files"] = sum(1 for u in units if u["kind"] == "assets")
    return info

