    info["unity_version"] = read_unity_version(data)
    managed = os.path.join(data, "Managed")
    asm = os.path.join(managed, "Assembly-CSharp.dll")
    meta = None
    for dp, _, fns in os.walk(data):
        if "global-metadata.dat" in fns:
            meta = os.path.join(dp, "global-metadata.dat")
            break
        # не уходим в StreamingAssets, там много файлов
        if dp.endswith("StreamingAssets"):
            _[:] = []
    ga = os.path.join(root, "GameAssembly.dll")
    if os.path.exists(ga) or meta:
        info["backend"] = "il2cpp"
        info["game_assembly"] = ga if os.path.exists(ga) else None
        info["global_metadata"] = meta
    elif os.path.exists(asm):
        info["backend"] = "mono"
    else:
        info["backend"] = "unknown"
    info["assembly_csharp"] = asm if os.path.exists(asm) else None
    info["managed_dir"] = managed if os.path.isdir(managed) else None
    info["assembly_csharp_firstpass"] = os.path.join(managed, "Assembly-CSharp-firstpass.dll") \
        if os.path.exists(os.path.join(managed, "Assembly-CSharp-firstpass.dll")) else None

    units = []  # {path, kind: bundle|assets|scene, size}

    def add(p, kind):
        units.append({"path": p, "kind": kind, "size": os.path.getsize(p), "rel": os.path.relpath(p, data).replace("\\", "/")})

    # сериализованные файлы в корне *_Data
    for fn in sorted(os.listdir(data)):
        p = os.path.join(data, fn)
        if not os.path.isfile(p) or fn.lower().endswith(SKIP_EXT):
            continue
        magic = sniff_magic(p)
        if magic:
            add(p, "bundle")
        elif re.match(r"^level\d+$", fn):
            add(p, "scene")
        elif SERIAL_NAME_RX.match(fn):
            add(p, "assets")
    # бандлы: StreamingAssets (включая aa/ Addressables) и прочие подкаталоги *_Data (кроме Managed/Mono/Plugins)
    for sub in sorted(os.listdir(data)):
        sp = os.path.join(data, sub)
        if not os.path.isdir(sp) or sub in ("Managed", "Mono", "MonoBleedingEdge", "Plugins", "il2cpp_data", "Resources"):
            continue
        for dp, _, fns in os.walk(sp):
            for fn in sorted(fns):
                p = os.path.join(dp, fn)
                if fn.lower().endswith(SKIP_EXT):
                    continue
                if os.path.getsize(p) < 64:
                    continue
                if sniff_magic(p):
                    add(p, "bundle")
    info["units"] = units
    info["streaming_assets"] = os.path.isdir(os.path.join(data, "StreamingAssets"))
    info["has_resources_assets"] = os.path.exists(os.path.join(data, "resources.assets"))
    info["n_levels"] = sum(1 for u in units if u["kind"] == "scene")
    info["n_bundles"] = sum(1 for u in units if u["kind"] == "bundle")
    info["n_assets_files"] = sum(1 for u in units if u["kind"] == "assets")
    return info

input.file_text:
"""Рабочие задачи, исполняются в дочерних процессах (multiprocessing).

Одна «job» = (файл, набор задач, шард). Результат пишется в stage-каталог job'а:
  stage/result.json   - строки таблиц (аним., коллайдеры, ...)
  stage/text/...      - TextAssets под контейнерными путями
  stage/prefabs/...   - JSON префабов
  stage/scenes/...    - JSON сцен (только с --scenes)
"""
import collections
import os
import re
import time
import traceback

from .common import (Cleaner, SKIP_CLASSES, category_of, fnum, folder_of, json_dump, log, merge_stats, safe_rel)

_GEN = {"gen": None, "tried": False}
_EXT_CACHE = {}

COLLIDERS_2D = {"BoxCollider2D", "CircleCollider2D", "CapsuleCollider2D", "PolygonCollider2D", "EdgeCollider2D",
                "CompositeCollider2D"}
COLLIDERS_3D = {"BoxCollider", "SphereCollider", "CapsuleCollider", "MeshCollider", "CharacterController"}
BODY = {0: "Dynamic", 1: "Kinematic", 2: "Static"}
SETTINGS_TYPES = ("TimeManager", "Physics2DSettings", "PhysicsManager", "QualitySettings", "PlayerSettings",
                  "TagManager", "AudioManager", "InputManager")
CURVE_LISTS = ("m_FloatCurves", "m_PositionCurves", "m_ScaleCurves", "m_EulerCurves", "m_RotationCurves")


# ------------------------------------------------------------------ окружение

def _setup_generator(opts):
    """TypeTreeGenerator нужен, когда в билде вырезаны typetree'ы MonoBehaviour (релизные .assets)."""
    if _GEN["tried"]:
        return _GEN["gen"]
    _GEN["tried"] = True
    if not opts.get("typetree_gen") or not opts.get("unity_version"):
        return None
    try:
        from UnityPy.helpers.TypeTreeGenerator import TypeTreeGenerator
        g = TypeTreeGenerator(opts["unity_version"])
        g.load_local_game(opts["game_root"])
        _GEN["gen"] = g
    except Exception as e:  # noqa
        log("TypeTreeGenerator недоступен (%s: %s) - MonoBehaviour без typetree будут с ошибкой", type(e).__name__, e)
    return _GEN["gen"]


def load_env(path, opts):
    import UnityPy
    if opts.get("unity_version"):
        try:
            UnityPy.config.FALLBACK_UNITY_VERSION = opts["unity_version"]
        except Exception:
            pass
    env = UnityPy.load(path)
    g = _setup_generator(opts)
    if g is not None:
        env.typetree_generator = g
    return env


class U:
    """Один SerializedFile: словарь объектов, контейнер, резолв PPtr в имена."""

    def __init__(self, env, sf, unit, opts, allow_ext=True):
        self.env, self.sf, self.unit, self.opts, self.allow_ext = env, sf, unit, opts, allow_ext
        self.objs = {}
        for o in env.objects:
            if o.assets_file is sf:
                self.objs[o.path_id] = o
        single = len({id(o.assets_file) for o in env.objects}) <= 1
        self.cont = {}   # pid -> [paths]
        for p, ptr in env.container.items():
            if ptr.file_id not in (0, None) and not single:
                continue
            if not single and getattr(ptr, "assetsfile", None) is not sf:
                continue
            self.cont.setdefault(ptr.path_id, []).append(p)
        for v in self.cont.values():
            v.sort()
        self._tt = {}
        self._names = {}
        self._scripts = {}
        self.errors = collections.Counter()
        self.err_samples = []

    # -- typetree
    def tt(self, pid, cache=True):
        if cache and pid in self._tt:
            return self._tt[pid]
        t = self.objs[pid].read_typetree()
        if cache:
            self._tt[pid] = t
        return t

    def err(self, where, e):
        k = "%s:%s" % (where, type(e).__name__)
        self.errors[k] += 1
        if len(self.err_samples) < 20:
            self.err_samples.append("%s %s: %s" % (self.unit["rel"], where, str(e)[:200]))

    # -- внешние файлы (только для plain *.assets игр)
    def ext(self, fid):
        if not self.allow_ext or fid <= 0:
            return None
        try:
            ext = self.sf.externals[fid - 1]
            base = os.path.basename(str(ext.path).replace("\\", "/")).lower()
        except Exception:
            return None
        files = self.opts.get("assets_by_name", {})
        path = files.get(base)
        if not path:
            return None
        if path not in _EXT_CACHE:
            try:
                env = load_env(path, self.opts)
                sfs = {id(o.assets_file): o.assets_file for o in env.objects}
                sf = next(iter(sfs.values())) if sfs else None
                _EXT_CACHE[path] = U(env, sf, {"rel": base}, self.opts, allow_ext=False) if sf else None
            except Exception:
                _EXT_CACHE[path] = None
        return _EXT_CACHE[path]

    # -- имена
    def name_of(self, pid):
        if pid in self._names:
            return self._names[pid]
        o = self.objs.get(pid)
        r = "?"
        if o is None:
            r = "?missing"
        elif pid in self.cont:
            r = self.cont[pid][0]
        else:
            try:
                tn = o.type.name
                if tn == "GameObject":
                    r = "GO:" + self.tt(pid)["m_Name"]
                elif tn == "MonoBehaviour":
                    t = self.tt(pid)
                    go = self.objs.get(t["m_GameObject"]["m_PathID"])
                    r = "MB:" + (self.tt(go.path_id)["m_Name"] if go is not None else "?")
                elif tn == "Shader":
                    t = self.tt(pid)
                    r = "Shader:" + (t.get("m_ParsedForm", {}).get("m_Name") or t.get("m_Name") or "")
                else:
                    try:
                        nm = o.peek_name()
                    except Exception:
                        nm = None
                    r = tn + (":" + nm if nm else "")
            except Exception:
                r = "err"
        self._names[pid] = r
        return r

    def ref_name(self, fid, pid):
        if fid == 0:
            return self.name_of(pid)
        x = self.ext(fid)
        if x is not None:
            return "ext:" + x.name_of(pid)
        return "ext:%d#%d" % (fid, pid)

    def script_class(self, ptr):
        fid, pid = ptr["m_FileID"], ptr["m_PathID"]
        key = (fid, pid)
        if key in self._scripts:
            return self._scripts[key]
        r = "MonoBehaviour"
        try:
            src = self if fid == 0 else self.ext(fid)
            if src is not None and pid in src.objs:
                r = src.tt(pid)["m_ClassName"]
            elif pid:
                r = "MonoBehaviour<ext:%d#%d>" % (fid, pid)
        except Exception:
            pass
        self._scripts[key] = r
        return r

    # -- иерархия
    def transform_of(self, gt):
        for c in gt["m_Component"]:
            pid = c["component"]["m_PathID"] if isinstance(c, dict) and "component" in c else None
            o = self.objs.get(pid)
            if o is not None and o.type.name in ("Transform", "RectTransform"):
                return pid, self.tt(pid)
        return None, None

    def root_go(self, goid):
        cur = goid
        for _ in range(64):
            _, tr = self.transform_of(self.tt(cur))
            if tr is None:
                return cur
            f = tr["m_Father"]
            if f["m_PathID"] == 0 or f["m_FileID"] != 0 or f["m_PathID"] not in self.objs:
                return cur
            cur = self.tt(f["m_PathID"])["m_GameObject"]["m_PathID"]
        return cur


# ------------------------------------------------------------------ TEXT

def task_text(u, stage, res):
    rows = []
    used = set()
    n = 0
    for pid, o in u.objs.items():
        if o.type.name != "TextAsset":
            continue
        try:
            d = o.read()
            name = d.m_Name
            data = d.m_Script
            data = data.encode("utf-8", "surrogateescape") if isinstance(data, str) else bytes(data)
            paths = u.cont.get(pid)
            p = safe_rel(paths[0]) if paths else "_noncontainer/%s/%s_%d.txt" % (safe_rel(u.unit["rel"]), safe_rel(name) or "noname", pid)
            if p.lower() in used:
                p = p + ".%d" % pid
            used.add(p.lower())
            fp = os.path.join(stage, "text", p)
            os.makedirs(os.path.dirname(fp), exist_ok=True)
            with open(fp, "wb") as f:
                f.write(data)
            rows.append([p, len(data), u.unit["rel"], "container" if paths else "noncontainer"])
            n += 1
        except Exception as e:
            u.err("text", e)
    res["text_rows"] = res.get("text_rows", []) + rows


# ------------------------------------------------------------------ PREFABS

def _flat_scalars(v, pre="", out=None, lim=80):
    if out is None:
        out = {}
    if len(out) >= lim:
        return out
    if isinstance(v, dict):
        for k, x in v.items():
            _flat_scalars(x, pre + ("." if pre else "") + k, out, lim)
    elif isinstance(v, list):
        for i, x in enumerate(v[:16]):
            _flat_scalars(x, "%s[%d]" % (pre, i), out, lim)
    elif isinstance(v, (bool, int, float)) or (isinstance(v, str) and len(v) <= 40):
        out[pre] = v
    return out


def _phys_row(cat, ppath, goname, layer, ws, cls, f):
    """Возвращает ('col'|'body', row). Колонки как в старом wol-ref/extra + хвост для 3D."""
    ax, ay, az = abs(ws[0]), abs(ws[1]), abs(ws[2]) if len(ws) > 2 else 1.0
    if cls in COLLIDERS_2D or cls in COLLIDERS_3D:
        d3 = cls in COLLIDERS_3D
        off = f.get("m_Center") if d3 else f.get("m_Offset")
        off = off or {}
        sx = sy = sz = r = h = ""
        wx = wy = wz = ""
        pts = ""
        if cls in ("CircleCollider2D", "SphereCollider"):
            r = f.get("m_Radius", 0)
            wx = wy = 2 * r * max(ax, ay, az if d3 else 0)
            wz = wx if d3 else ""
        elif cls in ("BoxCollider2D", "BoxCollider", "CapsuleCollider2D"):
            sz_ = f.get("m_Size", {}) or {}
            sx, sy = sz_.get("x", 0), sz_.get("y", 0)
            wx, wy = sx * ax, sy * ay
            if d3:
                sz = sz_.get("z", 0)
                wz = sz * az
        elif cls in ("CapsuleCollider", "CharacterController"):
            r = f.get("m_Radius", 0)
            h = f.get("m_Height", 0)
            wx = wz = 2 * r * max(ax, az)
            wy = h * ay
        elif cls == "PolygonCollider2D":
            pts = len((f.get("m_Points") or {}).get("m_Paths", []) or [])
        mat = (f.get("m_Material") or {}).get("ref", "")
        row = [ppath, cat, goname, layer, cls, f.get("m_IsTrigger", False), sx, sy, r, off.get("x", 0), off.get("y", 0),
               round(ax, 4), round(ay, 4), round(wx, 4) if wx != "" else "", round(wy, 4) if wy != "" else "", mat,
               "3D" if d3 else "2D", sz, off.get("z", "") if d3 else "", h, f.get("m_Direction", ""),
               round(wz, 4) if wz != "" else "", pts]
        return "col", row
    if cls == "Rigidbody2D":
        return "body", [ppath, cat, goname, layer, BODY.get(f.get("m_BodyType")), f.get("m_Mass"),
                        f.get("m_LinearDrag", f.get("m_LinearDamping")), f.get("m_AngularDrag", f.get("m_AngularDamping")),
                        f.get("m_GravityScale"), f.get("m_Constraints"), f.get("m_CollisionDetection"),
                        f.get("m_Interpolate"), f.get("m_SleepingMode"), "2D"]
    if cls == "Rigidbody":
        kin = f.get("m_IsKinematic")
        return "body", [ppath, cat, goname, layer, "Kinematic" if kin else "Dynamic", f.get("m_Mass"),
                        f.get("m_Drag", f.get("m_LinearDamping")), f.get("m_AngularDrag", f.get("m_AngularDamping")),
                        1 if f.get("m_UseGravity") else 0, f.get("m_Constraints"), f.get("m_CollisionDetection"),
                        f.get("m_Interpolate"), f.get("m_SleepingMode"), "3D"]
    return None, None


class PrefabCtx:
    def __init__(self, path, cat, cleaner):
        self.path, self.cat, self.cleaner = path, cat, cleaner
        self.cols, self.bodies, self.cams, self.curves = [], [], [], []
        self.classes = collections.Counter()
        self.ncomp = 0


def walk_go(u, goid, prefix, pscale, out, ctx, want_curves, depth=0):
    t = u.tt(goid)
    gname = t["m_Name"]
    comps = []
    scale = list(pscale)
    pos = lscale = None
    children = []
    skipped = collections.Counter()
    goname = prefix + gname
    for c in t["m_Component"]:
        if not (isinstance(c, dict) and "component" in c):
            continue
        cp = c["component"]
        if cp["m_FileID"] != 0:
            continue
        o = u.objs.get(cp["m_PathID"])
        if o is None:
            continue
        tn = o.type.name
        if tn in ("Transform", "RectTransform"):
            tt = u.tt(cp["m_PathID"])
            ls = tt["m_LocalScale"]
            lscale = [ls["x"], ls["y"], ls["z"]]
            scale = [pscale[i] * lscale[i] for i in range(3)]
            p = tt["m_LocalPosition"]
            pos = [p["x"], p["y"], p["z"]]
            children = [ch["m_PathID"] for ch in tt["m_Children"] if ch["m_FileID"] == 0]
            continue
        if tn in SKIP_CLASSES:
            skipped[tn] += 1
            continue
        try:
            tt = o.read_typetree()
            cls = u.script_class(tt["m_Script"]) if tn == "MonoBehaviour" else tn
            en = tt.get("m_Enabled", 1)
            cl = ctx.cleaner
            cl.curves = [] if want_curves else None
            fields = cl.clean(tt)
            if want_curves and cl.curves:
                for fpath, cc in cl.curves:
                    ctx.curves.append({"source": "mono", "owner": ctx.path, "go": goname, "component": cls,
                                       "field": fpath, "keys": cc["keys"], "preWrap": cc["pre"], "postWrap": cc["post"]})
            comps.append({"class": cls, "enabled": en, "fields": fields})
            ctx.classes[cls] += 1
            ctx.ncomp += 1
        except Exception as e:
            u.err("component:" + tn, e)
            comps.append({"class": tn, "error": "%s: %s" % (type(e).__name__, str(e)[:160])})
    layer = t.get("m_Layer")
    ws = scale
    for c in comps:
        if "fields" not in c:
            continue
        kind, row = _phys_row(ctx.cat, ctx.path, goname, layer, ws, c["class"], c["fields"])
        if kind == "col":
            ctx.cols.append(row)
        elif kind == "body":
            ctx.bodies.append(row)
        if c["class"] == "Camera":
            ctx.cams.append({"prefab": ctx.path, "go": goname, "layer": layer, "worldScale": scale, "fields": c["fields"],
                             "siblings": [{"class": s["class"], "fields": _flat_scalars(s["fields"])}
                                          for s in comps if s is not c and "fields" in s]})
    rec = {"go": goname, "active": t.get("m_IsActive", 1), "layer": layer, "tag": t.get("m_Tag"), "localPos": pos,
           "localScale": lscale, "worldScale": scale, "components": comps}
    if skipped:
        rec["skipped"] = dict(skipped)
    out.append(rec)
    if depth > 60:
        return
    for cp in children:
        try:
            if cp not in u.objs:
                continue
            cg = u.tt(cp)["m_GameObject"]["m_PathID"]
            walk_go(u, cg, goname + "/", scale, out, ctx, want_curves, depth + 1)
        except Exception as e:
            u.err("child", e)
            out.append({"go": goname + "/?", "error": str(e)[:160]})


def _root_gos(u):
    roots = []
    for pid, o in u.objs.items():
        if o.type.name != "GameObject":
            continue
        try:
            _, tr = u.transform_of(u.tt(pid))
            if tr is None or tr["m_Father"]["m_PathID"] == 0:
                roots.append(pid)
        except Exception as e:
            u.err("root", e)
    return roots


def task_prefabs(u, stage, res, shard, nshards, mode, want_curves):
    cleaner = Cleaner(u.ref_name)
    targets = []   # (path, pid, aliases)
    if mode == "scene":
        roots = _root_gos(u)
        targets = [("scene:" + u.unit["rel"], None, roots)]
    else:
        pp = [(ps, pid) for pid, ps in u.cont.items() for _ in [0] if any(x.lower().endswith(".prefab") for x in ps)]
        if pp:
            for pid, ps in u.cont.items():
                pf = [x for x in ps if x.lower().endswith(".prefab")]
                if pf and pid in u.objs and u.objs[pid].type.name == "GameObject":
                    targets.append((pf[0], pid, pf[1:]))
        elif not u.cont and u.unit["kind"] == "assets":
            for pid in _root_gos(u):
                nm = u.tt(pid)["m_Name"]
                targets.append(("_noncontainer/%s/%s_%d.prefab" % (safe_rel(u.unit["rel"]), safe_rel(nm) or "noname", pid), pid, []))
        targets.sort(key=lambda x: x[0])
        targets = targets[shard::nshards]
    idx, n_fail = [], 0
    for path, pid, extra in targets:
        ctx = PrefabCtx(path, category_of(path), cleaner)
        out = []
        try:
            if mode == "scene":
                for r in extra:
                    walk_go(u, r, "", [1, 1, 1], out, ctx, want_curves)
            else:
                walk_go(u, pid, "", [1, 1, 1], out, ctx, want_curves)
        except Exception as e:
            n_fail += 1
            u.err("prefab", e)
            traceback.print_exc()
            continue
        if mode == "scene":
            fp = os.path.join(stage, "scenes", safe_rel(u.unit["rel"]) + ".json")
            doc = {"scene": u.unit["rel"], "objects": out}
        else:
            rel = re.sub(r"\.prefab$", "", safe_rel(path), flags=re.I) + ".json"
            fp = os.path.join(stage, "prefabs", rel)
            doc = {"path": path, "kind": ctx.cat, "aliases": extra, "objects": out}
        json_dump(doc, fp, indent=1)
        idx.append([path, ctx.cat, len(out), ctx.ncomp, ";".join(sorted(ctx.classes)), ";".join(extra),
                    os.path.relpath(fp, stage).replace("\\", "/")])
        for k in ("cols", "bodies", "cams", "curves"):
            res.setdefault("prefab_" + k, []).extend(getattr(ctx, k))
    res.setdefault("prefab_index", []).extend(idx)
    res["prefab_failed"] = res.get("prefab_failed", 0) + n_fail


# ------------------------------------------------------------------ ANIM

def _clip_info(u, pid, cache, want_curves, curve_out):
    if pid in cache:
        return cache[pid]
    o = u.objs.get(pid)
    if o is None or o.type.name != "AnimationClip":
        cache[pid] = None
        return None
    t = u.tt(pid, cache=False)
    mc = t["m_MuscleClip"]
    path = (u.cont.get(pid) or [""])[0]
    d = {"name": t["m_Name"], "len": mc["m_StopTime"] - mc["m_StartTime"], "fps": t["m_SampleRate"],
         "loop": bool(mc["m_LoopTime"]),
         "events": [(e["time"], e["functionName"], e["data"], e["floatParameter"], e["intParameter"]) for e in t.get("m_Events", [])],
         "path": path}
    d["n_curves"] = {k: len(t.get(k, []) or []) for k in CURVE_LISTS}
    d["n_ppt"] = len(t.get("m_PPtrCurves", []) or [])
    try:
        d["n_baked"] = len(t["m_ClipBindingConstant"]["genericBindings"])
    except Exception:
        d["n_baked"] = 0
    if want_curves:
        owner = path or ("%s::%s" % (u.unit["rel"], t["m_Name"]))
        for key in CURVE_LISTS:
            for fc in t.get(key, []) or []:
                try:
                    cur = fc["curve"]
                    from .common import compact_curve
                    cc = compact_curve(cur)
                    curve_out.append({"source": "clip", "owner": owner, "clip": t["m_Name"], "kind": key,
                                      "field": fc.get("attribute") or key, "target_path": fc.get("path", ""),
                                      "keys": cc["keys"], "preWrap": cc["pre"], "postWrap": cc["post"]})
                except Exception as e:
                    u.err("clipcurve", e)
    cache[pid] = d
    return d


def task_anim(u, stage, res, want_curves):
    owners = collections.defaultdict(set)
    for pid, o in u.objs.items():
        if o.type.name != "Animator":
            continue
        try:
            t = u.tt(pid, cache=False)
            cp = t["m_Controller"]
            if not cp["m_PathID"] or cp["m_FileID"] != 0:
                continue
            go = t["m_GameObject"]["m_PathID"]
            if go not in u.objs:
                continue
            r = u.root_go(go)
            pp = u.cont.get(r)
            owners[cp["m_PathID"]].add(pp[0] if pp else "(noncontainer root %s)" % u.tt(r)["m_Name"])
        except Exception as e:
            u.err("animator", e)
    clip_rows, ev_rows, tr_rows, cache, curve_out = [], [], [], {}, []
    for pid, o in u.objs.items():
        if o.type.name != "AnimatorController":
            continue
        try:
            t = u.tt(pid, cache=False)
            cpath = (u.cont.get(pid) or ["(noncontainer)"])[0]
            cname = t["m_Name"]
            tos = {a: b for a, b in t["m_TOS"]}
            clips = [c["m_PathID"] for c in t["m_AnimationClips"]]
            ol = sorted(owners.get(pid, []), key=lambda x: (0 if re.search(r"/prefabs/", x) else 1, x))
            own = ";".join(ol[:4]) + (";(+%d more)" % (len(ol) - 4) if len(ol) > 4 else "")
            for li, sm in enumerate(t["m_Controller"]["m_StateMachineArray"]):
                sm = sm["data"]
                st_names = {}
                for si, s in enumerate(sm["m_StateConstantArray"]):
                    s = s["data"]
                    nm = tos.get(s["m_NameID"]) or tos.get(s.get("m_PathID")) or ""
                    nm = nm.split(".")[-1] if nm else "(hash %d)" % s["m_NameID"]
                    st_names[si] = nm
                for si, s in enumerate(sm["m_StateConstantArray"]):
                    s = s["data"]
                    nm = st_names[si]
                    cl_ids = []
                    for bt in s["m_BlendTreeConstantArray"]:
                        for n in bt["data"]["m_NodeArray"]:
                            n = n["data"]
                            if n["m_ClipID"] != 4294967295 and (n["m_BlendType"] is not None):
                                cl_ids.append(n["m_ClipID"])
                    kind = "blend" if len(cl_ids) > 1 else "clip"
                    for ci in cl_ids:
                        cpid = clips[ci] if ci < len(clips) else 0
                        info = _clip_info(u, cpid, cache, False, None)
                        if not info:
                            continue
                        speed = s["m_Speed"]
                        clip_rows.append([cpath, cname, own, li, nm, info["name"], round(info["len"], 4), info["fps"],
                                          info["loop"], speed, round(info["len"] / speed, 4) if speed else "", kind,
                                          len(info["events"]), info["path"]])
                    for tc in s["m_TransitionConstantArray"]:
                        tc = tc["data"]
                        tr_rows.append([cname, li, nm, st_names.get(tc.get("m_DestinationState"), tc.get("m_DestinationState")),
                                        tc.get("m_HasExitTime", tc.get("m_Atomic")), tc.get("m_ExitTime"),
                                        tc.get("m_TransitionDuration"), tc.get("m_TransitionOffset"),
                                        tc.get("m_HasFixedDuration"), len(tc.get("m_ConditionConstantArray", []))])
                for tc in sm["m_AnyStateTransitionConstantArray"]:
                    tc = tc["data"]
                    tr_rows.append([cname, li, "(Any)", st_names.get(tc.get("m_DestinationState"), tc.get("m_DestinationState")),
                                    tc.get("m_HasExitTime"), tc.get("m_ExitTime"), tc.get("m_TransitionDuration"),
                                    tc.get("m_TransitionOffset"), tc.get("m_HasFixedDuration"),
                                    len(tc.get("m_ConditionConstantArray", []))])
        except Exception as e:
            u.err("controller", e)
    used = set(cache)
    # все клипы (в т.ч. не привязанные к контроллеру этого файла)
    all_rows, ev_all = [], []
    for pid, o in u.objs.items():
        if o.type.name != "AnimationClip":
            continue
        try:
            info = _clip_info(u, pid, cache, want_curves, curve_out)
            if not info:
                continue
            nc = info["n_curves"]
            all_rows.append([info["path"] or u.unit["rel"], info["name"], round(info["len"], 4), info["fps"], info["loop"],
                             len(info["events"]), nc["m_FloatCurves"], nc["m_PositionCurves"] + nc["m_RotationCurves"] +
                             nc["m_EulerCurves"] + nc["m_ScaleCurves"], info["n_ppt"], info["n_baked"], int(pid in used)])
        except Exception as e:
            u.err("clip", e)
    for pid in used:
        ci = cache.get(pid)
        if not ci:
            continue
        for (tm, fn, dat, fp, ip) in ci["events"]:
            ev_rows.append([ci["path"], ci["name"], round(ci["len"], 4), round(tm, 4), fn, dat, fp, ip])
    res["anim_clips"] = res.get("anim_clips", []) + clip_rows
    res["anim_events"] = res.get("anim_events", []) + ev_rows
    res["anim_transitions"] = res.get("anim_transitions", []) + tr_rows
    res["anim_all_clips"] = res.get("anim_all_clips", []) + all_rows
    res["clip_curves"] = res.get("clip_curves", []) + curve_out
    res["clips_baked"] = res.get("clips_baked", 0) + sum(1 for r in all_rows if r[9] and not (r[6] or r[7]))


# ------------------------------------------------------------------ SETTINGS

def task_settings(u, stage, res):
    cl = Cleaner(u.ref_name)
    out = res.setdefault("settings", {})
    for pid, o in u.objs.items():
        tn = o.type.name
        if tn in SETTINGS_TYPES:
            try:
                out[tn] = cl.clean(u.tt(pid, cache=False))
            except Exception as e:
                u.err("settings:" + tn, e)


# ------------------------------------------------------------------ INVENTORY

def _tex_fmt(i):
    try:
        from UnityPy.enums import TextureFormat
        return TextureFormat(i).name
    except Exception:
        return str(i)


def _bucket(m):
    for b in (16, 32, 64, 128, 256, 512, 1024):
        if m <= b:
            return "<=%d" % b
    return ">1024"


def task_inventory(u, stage, res, depth):
    inv = res.setdefault("inventory", {})
    # текстуры -> папка (для спрайтов без собственного контейнерного пути)
    def group_of(pid):
        ps = u.cont.get(pid)
        return folder_of(ps[0], depth) if ps else None
    unc = "(uncontained)/" + u.unit["rel"]
    for pid, o in u.objs.items():
        tn = o.type.name
        grp = group_of(pid)
        stat = {"count": 1}
        try:
            if tn == "Texture2D":
                t = u.tt(pid, cache=False)
                w, h = t.get("m_Width", 0), t.get("m_Height", 0)
                stat.update({"formats": {_tex_fmt(t.get("m_TextureFormat", -1)): 1}, "sizes": {"%dx%d" % (w, h): 1},
                             "total_px": w * h, "max_px": w * h})
            elif tn == "Sprite":
                t = u.tt(pid, cache=False)
                r = t.get("m_Rect", {})
                w, hh = r.get("width", 0), r.get("height", 0)
                stat.update({"ppu": {str(fnum(round(t.get("m_PixelsToUnits", 0), 3))): 1},
                             "size_buckets": {_bucket(max(w, hh)): 1}})
                if grp is None:
                    tx = (t.get("m_RD", {}) or {}).get("texture", {})
                    if tx and tx.get("m_FileID") == 0:
                        grp = group_of(tx["m_PathID"])
            elif tn == "AudioClip":
                t = u.tt(pid, cache=False)
                ln = t.get("m_Length", 0) or 0
                stat.update({"total_length_s": round(ln, 3), "max_length_s": round(ln, 3),
                             "channels": {str(t.get("m_Channels")): 1}, "frequency": {str(t.get("m_Frequency")): 1}})
            elif tn == "Mesh":
                t = u.tt(pid, cache=False)
                vc = (t.get("m_VertexData") or {}).get("m_VertexCount", 0)
                tri = 0
                for sm in t.get("m_SubMeshes", []) or []:
                    if sm.get("topology", 0) == 0:
                        tri += sm.get("indexCount", 0) // 3
                stat.update({"vertices": vc, "triangles": tri, "max_vertices": vc, "max_triangles": tri})
            elif tn == "Material":
                t = u.tt(pid, cache=False)
                sh = t.get("m_Shader", {})
                shn = u.ref_name(sh.get("m_FileID", 0), sh["m_PathID"]) if sh and sh.get("m_PathID") else "none"
                stat["shaders"] = {shn: 1}
            elif tn == "Shader":
                t = u.tt(pid, cache=False)
                stat["names"] = {(t.get("m_ParsedForm", {}).get("m_Name") or t.get("m_Name") or "?"): 1}
        except Exception as e:
            u.err("inv:" + tn, e)
        g = grp or unc
        merge_stats(inv.setdefault(g, {}).setdefault(tn, {}), stat)


# ------------------------------------------------------------------ JOB

def run_job(job):
    t00 = time.time()
    out = {"job": job["id"], "ok": True, "timings": {}, "errors": {}, "err_samples": []}
    stage = job["stage"]
    try:
        os.makedirs(stage, exist_ok=True)
        opts = job["opts"]
        unit = job["unit"]
        env = load_env(unit["path"], opts)
        out["timings"]["load"] = round(time.time() - t00, 2)
        sfs = {}
        for o in env.objects:
            sfs.setdefault(id(o.assets_file), o.assets_file)
        res = {}
        errs = collections.Counter()
        samples = []
        n_obj = 0
        for sf in sfs.values():
            u = U(env, sf, unit, opts)
            n_obj += len(u.objs)
            for task in job["tasks"]:
                t0 = time.time()
                if task == "text":
                    task_text(u, stage, res)
                elif task == "prefabs":
                    task_prefabs(u, stage, res, job["shard"], job["nshards"], job["mode"], opts["curves"] != "none")
                elif task == "anim":
                    task_anim(u, stage, res, opts["curves"] == "all")
                elif task == "settings":
                    task_settings(u, stage, res)
                elif task == "inventory":
                    task_inventory(u, stage, res, opts["inv_depth"])
                out["timings"][task] = round(out["timings"].get(task, 0) + time.time() - t0, 2)
            errs.update(u.errors)
            samples.extend(u.err_samples)
        out["n_objects"] = n_obj
        out["errors"] = dict(errs)
        out["err_samples"] = samples[:20]
        json_dump(res, os.path.join(stage, "result.json"), indent=None)
    except Exception as e:  # noqa
        out["ok"] = False
        out["error"] = "%s: %s" % (type(e).__name__, e)
        out["trace"] = traceback.format_exc()[-1500:]
    out["total_s"] = round(time.time() - t00, 2)
    return out

