def _n(x, d=None):
    return d if x is None else x


def mm(c):
    """MinMaxCurve -> (scalar, min). min пусто, если не режим 'две константы'."""
    if not isinstance(c, dict):
        return (c if isinstance(c, (int, float)) else ""), ""
    st = c.get("minMaxState")
    sc = c.get("scalar", c.get("m_Scalar", ""))
    mn = c.get("minScalar", "") if st in (3, 2) else ""
    return sc, mn


# ------------------------------------------------------------------ vfx_particles

def vfx_go(ctx, goname, depth, gt, raw, rect):
    byc = {}
    for cls, tn, tt in raw:
        byc.setdefault(tn, tt)
    rend = byc.get("ParticleSystemRenderer", {})
    ps = byc.get("ParticleSystem")
    sort_layer = rend.get("m_SortingLayerID", rend.get("m_SortingLayer", ""))
    sort_order = rend.get("m_SortingOrder", "")
    rmode = rend.get("m_RenderMode", "")
    mat = ""
    mats = rend.get("m_Materials") or []
