def scan_input(tt, source, tabs):
    """Ищет в произвольном typetree словарь с actions[{id,name}] и *Maps[{elementMaps}]."""
    found = [0]

    def rec(d, depth=0):
        if depth > 8:
            return
        if isinstance(d, dict):
            acts = d.get("actions")
            if isinstance(acts, list) and acts and isinstance(acts[0], dict) and "id" in acts[0] and "name" in acts[0]:
                found[0] += 1
                names = {}
                for a in acts:
                    names[a["id"]] = a["name"]
                    tabs["input_actions"].append([source, a["id"], a["name"], a.get("type", ""), a.get("categoryId", ""),
                                                  a.get("userAssignable", ""), a.get("behaviorId", "")])
                for k, v in d.items():
                    if _MAP_KEYS.search(k) and isinstance(v, list):
                        for m in v:
                            if not isinstance(m, dict):
                                continue
                            for em in m.get("elementMaps", []) or []:
                                mods = [str(em.get(x)) for x in ("modifierKey1", "modifierKey2", "modifierKey3") if em.get(x)]
                                skip = {"actionId", "elementType", "elementIdentifierId", "axisRange", "axisContribution",
                                        "keyboardKeyCode", "modifierKey1", "modifierKey2", "modifierKey3", "elementIdentifierName"}
                                extra = ";".join("%s=%s" % (kk, vv) for kk, vv in em.items()
                                                 if kk not in skip and isinstance(vv, (int, float, bool)))
                                tabs["input_default_bindings"].append([
                                    source, k, m.get("id", ""), m.get("name", ""), m.get("layoutId", ""), m.get("categoryId", ""),
                                    em.get("actionId", ""), names.get(em.get("actionId"), ""), em.get("elementType", ""),
                                    em.get("elementIdentifierId", ""), em.get("axisRange", ""), em.get("axisContribution", ""),
                                    em.get("keyboardKeyCode", ""), ";".join(mods), extra])
            for v in d.values():
                if isinstance(v, (dict, list)):
                    rec(v, depth + 1)
        elif isinstance(d, list):
            for v in d[:4000]:
                if isinstance(v, (dict, list)):
                    rec(v, depth + 1)
    rec(tt)
    return found[0]


def input_go(ctx, goname, depth, gt, raw, rect):
    for cls, tn, tt in raw:
        if tn == "MonoBehaviour" and re.search(r"input|rewired", cls, re.I):
