def tiled_tables(text_root):
    import os
    import xml.etree.ElementTree as ET
    sets, maps = [], []
    for dp, _, fns in os.walk(text_root):
        for fn in sorted(fns):
            if not fn.lower().endswith((".xml", ".tsx", ".tmx")):
                continue
            p = os.path.join(dp, fn)
            rel = os.path.relpath(p, text_root).replace("\\", "/")
            try:
                with open(p, "rb") as f:
                    head = f.read(400)
                if b"<tileset" not in head and b"<map" not in head:
                    continue
                root = ET.parse(p).getroot()
            except Exception:
                continue
            if root.tag == "tileset":
                img = root.find("image")
                tw, th = int(root.get("tilewidth", 0) or 0), int(root.get("tileheight", 0) or 0)
                iw = int(img.get("width", 0)) if img is not None else 0
                ih = int(img.get("height", 0)) if img is not None else 0
                cols = root.get("columns") or (iw // tw if tw else "")
                cnt = root.get("tilecount") or ((iw // tw) * (ih // th) if tw and th else "")
                sets.append([rel, root.get("name", ""), tw, th, iw, ih, cols, cnt])
            elif root.tag == "map":
                nonempty = 0
                for d in root.iter("data"):
                    if d.get("encoding") == "csv" and d.text:
                        nonempty += sum(1 for x in d.text.replace("\n", "").split(",") if x.strip() not in ("", "0"))
                maps.append([rel, root.get("width"), root.get("height"), root.get("tilewidth"), root.get("tileheight"),
                             len(root.findall("layer")), len(root.findall("tileset")),
                             sum(1 for _ in root.iter("object")), nonempty])
    return sets, maps

