                ctx.path, goname, tt.get("m_RenderMode"), tt.get("m_SortingOrder"), tt.get("m_PlaneDistance"),
                tt.get("m_OverrideSorting"), sc.get("m_UiScaleMode", ""), rr.get("x", ""), rr.get("y", ""),
                sc.get("m_MatchWidthOrHeight", ""), sc.get("m_ReferencePixelsPerUnit", "")])


# ------------------------------------------------------------------ input_bindings (Rewired и подобные)

_MAP_KEYS = re.compile(r"(keyboard|mouse|joystick|customcontroller)maps?$", re.I)


def scan_input(tt, source, tabs):
    """Ищет в произвольном typetree словарь с actions[{id,name}] и *Maps[{elementMaps}]."""
    found = [0]

    def rec(d, depth=0):
        if depth > 8:
            return
        if isinstance(d, dict):
            acts = d.get("actions")
            if isinstance(acts, list) and acts and isinstance(acts[0], dict) and "id" in acts[0] and "name" in acts[0]:
                found[0] += 1
                names = {}
                for a in acts:
                    names[a["id"]] = a["name"]
                    tabs["input_actions"].append([source, a["id"], a["name"], a.get("type", ""), a.get("categoryId", ""),
                                                  a.get("userAssignable", ""), a.get("behaviorId", "")])
                for k, v in d.items():
                    if _MAP_KEYS.search(k) and isinstance(v, list):
                        for m in v:
                            if not isinstance(m, dict):
                                continue
                            for em in m.get("elementMaps", []) or []:
                                mods = [str(em.get(x)) for x in ("modifierKey1", "modifierKey2", "modifierKey3") if em.get(x)]
                                skip = {"actionId", "elementType", "elementIdentifierId", "axisRange", "axisContribution",
                                        "keyboardKeyCode", "modifierKey1", "modifierKey2", "modifierKey3", "elementIdentifierName"}
                                extra = ";".join("%s=%s" % (kk, vv) for kk, vv in em.items()
                                                 if kk not in skip and isinstance(vv, (int, float, bool)))
                                tabs["input_default_bindings"].append([
                                    source, k, m.get("id", ""), m.get("name", ""), m.get("layoutId", ""), m.get("categoryId", ""),
                                    em.get("actionId", ""), names.get(em.get("actionId"), ""), em.get("elementType", ""),
                                    em.get("elementIdentifierId", ""), em.get("axisRange", ""), em.get("axisContribution", ""),
                                    em.get("keyboardKeyCode", ""), ";".join(mods), extra])
            for v in d.values():
                if isinstance(v, (dict, list)):
                    rec(v, depth + 1)
        elif isinstance(d, list):
            for v in d[:4000]:
                if isinstance(v, (dict, list)):
                    rec(v, depth + 1)
    rec(tt)
    return found[0]


def input_go(ctx, goname, depth, gt, raw, rect):
    for cls, tn, tt in raw:
        if tn == "MonoBehaviour" and re.search(r"input|rewired", cls, re.I):
            scan_input(tt, "%s::%s" % (ctx.path, goname), ctx.tables)


# ------------------------------------------------------------------ tilesets_themes_decor

_DECOR_RX = re.compile(r"decorat|doodad|randomiz|variant|scatter|propspawn", re.I)


def decor_go(ctx, goname, depth, gt, raw, rect):
    for cls, tn, tt in raw:
        if tn == "Tilemap":
            ctx.tab("unity_tilemaps").append([ctx.path, goname, len(tt.get("m_Tiles", []) or [])])
        elif tn == "MonoBehaviour" and _DECOR_RX.search(cls):
            for k, v in tt.items():
                if isinstance(v, list) and v and not k.startswith("m_Obj"):
                    keys = {str(x.get("m_PathID")) if isinstance(x, dict) and "m_PathID" in x else str(x) for x in v}
                    ctx.tab("decor_variants").append([ctx.path, goname, cls, k, len(v), len(keys)])


GO_COLLECTORS = {"vfx_particles": vfx_go, "lighting_setups": light_go, "audio_cues": audio_go, "ui_surfaces": ui_go,
                 "input_bindings": input_go, "tilesets_themes_decor": decor_go}


# ------------------------------------------------------------------ tiled XML (main-side, по data/text)

def tiled_tables(text_root):
    import os
    import xml.etree.ElementTree as ET
    sets, maps = [], []
    for dp, _, fns in os.walk(text_root):
        for fn in sorted(fns):
            if not fn.lower().endswith((".xml", ".tsx", ".tmx")):
                continue
            p = os.path.join(dp, fn)
            rel = os.path.relpath(p, text_root).replace("\\", "/")
            try:
                with open(p, "rb") as f:
                    head = f.read(400)
                if b"<tileset" not in head and b"<map" not in head:
                    continue
                root = ET.parse(p).getroot()
            except Exception:
                continue
            if root.tag == "tileset":
                img = root.find("image")
                tw, th = int(root.get("tilewidth", 0) or 0), int(root.get("tileheight", 0) or 0)
                iw = int(img.get("width", 0)) if img is not None else 0
                ih = int(img.get("height", 0)) if img is not None else 0
                cols = root.get("columns") or (iw // tw if tw else "")
                cnt = root.get("tilecount") or ((iw // tw) * (ih // th) if tw and th else "")
                sets.append([rel, root.get("name", ""), tw, th, iw, ih, cols, cnt])
            elif root.tag == "map":
                nonempty = 0
                for d in root.iter("data"):
                    if d.get("encoding") == "csv" and d.text:
                        nonempty += sum(1 for x in d.text.replace("\n", "").split(",") if x.strip() not in ("", "0"))
                maps.append([rel, root.get("width"), root.get("height"), root.get("tilewidth"), root.get("tileheight"),
                             len(root.findall("layer")), len(root.findall("tileset")),
                             sum(1 for _ in root.iter("object")), nonempty])
    return sets, maps

