#!/usr/bin/env python
"""make_catalog.py --data <ref_dir>/data --rules <rules.yaml> --out <dir> [--src <ref_dir>/src] [--only id,id]

Универсальный генератор каталогов (таблиц) по декларативным правилам YAML.
Выход на каждый каталог: <out>/<id>.csv, <out>/<id>.md, YAML-записи (id, kind, numbers{}, attrs{}, source_ref).
В каталоги попадают ТОЛЬКО id и числа: имена/описания (display text) отсекаются text-guard'ом и
списком запрещённых источников (forbid_sources). Подробности - README.md.
"""
import argparse
import ast
import csv
import fnmatch
import glob
import json
import math
import os
import re
import sys
import time
from collections import OrderedDict, defaultdict

try:
    import yaml
except ImportError:
    sys.exit("Нужен PyYAML: .venv\\Scripts\\python.exe -I make_catalog.py ... (см. README.md)")

MISSING = object()
VERSION = "1.0"


def log(msg, *a):
    sys.stderr.write("[%s] %s\n" % (time.strftime("%H:%M:%S"), (msg % a) if a else msg))
    sys.stderr.flush()


# ------------------------------------------------------------------ язык путей

_TOK = re.compile(r"""\[\*\]|\[\?(?P<fk>[^=\]]+)==(?P<fv>[^\]]*)\]|\[(?P<idx>-?\d+)\]|\['(?P<qk>[^']*)'\]|(?P<k>[^.\[\]]+)""")


def parse_path(path):
    toks, pos = [], 0
    path = path.strip()
    if path in ("", "$"):
        return toks
    if path.startswith("$."):
        path = path[2:]
    elif path.startswith("$"):
        path = path[1:]
    while pos < len(path):
        if path[pos] == ".":
            pos += 1
            continue
        m = _TOK.match(path, pos)
        if not m:
            raise ValueError("не разобрать путь %r на позиции %d" % (path, pos))
        if m.group(0) == "[*]":
            toks.append(("all",))
        elif m.group("fk") is not None:
            toks.append(("filter", m.group("fk").strip(), m.group("fv").strip().strip("'\"")))
        elif m.group("idx") is not None:
            toks.append(("idx", int(m.group("idx"))))
        elif m.group("qk") is not None:
            toks.append(("key", m.group("qk")))
        else:
            toks.append(("key", m.group("k")))
        pos = m.end()
    return toks


_PATH_CACHE = {}


def get_path(obj, path):
    """-> значение | MISSING | list (если был [*] или [?k==v])"""
    toks = _PATH_CACHE.get(path)
    if toks is None:
        toks = _PATH_CACHE[path] = parse_path(path)
    vals, wild = [obj], False
    for t in toks:
        new = []
        for v in vals:
            if t[0] == "key":
                if isinstance(v, dict) and t[1] in v:
                    new.append(v[t[1]])
            elif t[0] == "idx":
                if isinstance(v, list) and -len(v) <= t[1] < len(v):
                    new.append(v[t[1]])
            elif t[0] == "all":
                if isinstance(v, list):
                    new.extend(v)
                elif isinstance(v, dict):
                    new.extend(v.values())
                wild = True
            elif t[0] == "filter":
                if isinstance(v, list):
                    new.extend(x for x in v if isinstance(x, dict) and str(x.get(t[1])) == t[2])
                wild = True
        vals = new
    if wild:
        return vals
    return vals[0] if vals else MISSING


# ------------------------------------------------------------------ значения и редьюсеры

def to_num(v):
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if s in ("True", "true"):
            return True
        if s in ("False", "false"):
            return False
        try:
            f = float(s)
            return int(f) if f.is_integer() and re.fullmatch(r"-?\d+", s) else f
        except ValueError:
            return MISSING
    return MISSING


def flat(v):
    if isinstance(v, list):
        out = []
        for x in v:
            out.extend(flat(x))
        return out
    return [v]


def reduce_array(v, how):
    if v is MISSING:
        return MISSING
    if how is None:
        how = "first"
    if how.startswith("index:"):
        i = int(how.split(":", 1)[1])
        l = flat(v)
        return l[i] if -len(l) <= i < len(l) else MISSING
    l = [x for x in flat(v) if x is not MISSING and x is not None]
    if how == "all":
        return l
    if how == "len":
        return len(l)
    if how == "join":
        return "|".join(str(x) for x in l)
    if not l:
        return MISSING
    if how == "first":
        return l[0]
    if how == "last":
        return l[-1]
    nums = [to_num(x) for x in l]
    nums = [x for x in nums if x is not MISSING and not isinstance(x, bool)]
    if how in ("min", "max", "sum", "avg"):
        if not nums:
            return MISSING
        return {"min": min, "max": max, "sum": sum, "avg": lambda a: sum(a) / len(a)}[how](nums)
    if how == "nunique":
        return len(set(map(str, l)))
    if how == "any":
        return any(bool(x) for x in l)
    raise ValueError("неизвестный array/agg: %s" % how)


# ------------------------------------------------------------------ pipeline ключей: "path | tf:arg | tf"

def _tf(v, name, arg):
    if v is MISSING or v is None:
        return MISSING
    if isinstance(v, list):
        out = []
        for x in v:
            y = _tf(x, name, arg)
            if isinstance(y, list):
                out.extend(y)
            elif y is not MISSING:
                out.append(y)
        return out
    s = str(v)
    if name == "lower":
        return s.lower()
    if name == "upper":
        return s.upper()
    if name == "strip":
        return s.strip()
    if name == "stem":
        return os.path.splitext(os.path.basename(s.replace("\\", "/")))[0]
    if name == "basename":
        return os.path.basename(s.replace("\\", "/"))
    if name == "dirname":
        return os.path.dirname(s.replace("\\", "/"))
    if name == "strip_prefix":
        return s[len(arg):] if s.startswith(arg) else s
    if name == "strip_suffix":
        return s[:-len(arg)] if arg and s.endswith(arg) else s
    if name == "prefix_add":
        return arg + s
    if name == "split":
        return [x for x in s.split(arg) if x != ""]
    if name == "regex":
        m = re.search(arg, s)
        return (m.group(1) if m.groups() else m.group(0)) if m else MISSING
    if name == "replace":
        a, _, b = arg.partition("=>")
        return s.replace(a, b)
    if name == "int":
        n = to_num(v)
        return int(n) if n is not MISSING else MISSING
    if name == "str":
        return s
    if name == "first":
        return s
    raise ValueError("неизвестный transform: %s" % name)


def split_pipe(expr):
    """разбивает по '|', но не внутри кавычек/скобок"""
    out, cur, q, dep = [], "", None, 0
    for ch in expr:
        if q:
            cur += ch
            if ch == q:
                q = None
        elif ch in "'\"":
            q = ch
            cur += ch
        elif ch in "[(":
            dep += 1
            cur += ch
        elif ch in "])":
            dep -= 1
            cur += ch
        elif ch == "|" and dep == 0:
            out.append(cur.strip())
            cur = ""
        else:
            cur += ch
    out.append(cur.strip())
    return out


def eval_pipe(expr, rec, meta):
    """rec - raw запись; meta - {'$id','$stem','$file',...}"""
    parts = split_pipe(expr)
    head = parts[0]
    if head.startswith("$") and head in meta:
        v = meta[head]
    elif head.startswith("$") and head.split(".")[0] in meta:
        v = MISSING
    else:
        v = get_path(rec, head)
    for p in parts[1:]:
        name, _, arg = p.partition(":")
        if name == "array":
            v = reduce_array(v, arg)
        else:
            v = _tf(v, name.strip(), arg)
    if isinstance(v, list) and len(v) == 1 and not expr.rstrip().endswith("split"):
        pass
    return v


_TPL = re.compile(r"\{([^{}]+)\}")


def eval_key(spec, rec, meta):
    """spec: строка-pipeline или шаблон с {...}"""
    if "{" in spec:
        def rep(m):
            v = eval_pipe(m.group(1), rec, meta)
            v = reduce_array(v, "first") if isinstance(v, list) else v
            return "" if v is MISSING else str(v)
        return _TPL.sub(rep, spec)
    v = eval_pipe(spec, rec, meta)
    if isinstance(v, list):
        v = reduce_array(v, "first")
    return v


# ------------------------------------------------------------------ безопасные выражения

_FUNCS = {
    "min": min, "max": max, "abs": abs, "round": round, "len": len, "float": float, "int": int, "str": str,
    "lower": lambda s: str(s).lower(), "upper": lambda s: str(s).upper(),
    "startswith": lambda s, p: str(s).startswith(p), "endswith": lambda s, p: str(s).endswith(p),
    "contains": lambda s, p: p in str(s), "re": lambda p, s: re.search(p, str(s)) is not None,
    "coalesce": lambda *a: next((x for x in a if x not in (None, "", MISSING)), None),
    "clamp": lambda x, lo, hi: max(lo, min(hi, x)), "floor": math.floor, "ceil": math.ceil, "sqrt": math.sqrt,
    "isnum": lambda x: isinstance(x, (int, float)) and not isinstance(x, bool),
}
_OK_NODES = (ast.Expression, ast.BoolOp, ast.BinOp, ast.UnaryOp, ast.Compare, ast.Constant, ast.Name, ast.Call,
             ast.IfExp, ast.List, ast.Tuple, ast.Load, ast.And, ast.Or, ast.Not, ast.Add, ast.Sub, ast.Mult, ast.Div,
             ast.FloorDiv, ast.Mod, ast.Pow, ast.USub, ast.UAdd, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
             ast.In, ast.NotIn, ast.Is, ast.IsNot)
_EXPR_CACHE = {}


def compile_expr(expr):
    c = _EXPR_CACHE.get(expr)
    if c is None:
        tree = ast.parse(expr, mode="eval")
        for n in ast.walk(tree):
            if not isinstance(n, _OK_NODES):
                raise ValueError("запрещённая конструкция %s в выражении %r" % (type(n).__name__, expr))
            if isinstance(n, ast.Call) and not (isinstance(n.func, ast.Name) and n.func.id in _FUNCS):
                raise ValueError("запрещённый вызов в %r" % expr)
        c = _EXPR_CACHE[expr] = compile(tree, "<expr>", "eval")
    return c


def safe_eval(expr, env):
    return eval(compile_expr(expr), {"__builtins__": {}}, dict(_FUNCS, **env))


# ------------------------------------------------------------------ загрузчики источников

class Ctx:
    def __init__(self, data, src, forbid):
        self.data, self.src, self.forbid = data, src, [re.compile(p, re.I) for p in forbid]
        self.cache = {}
        self.cs_classes = None
        self.warn = defaultdict(int)


def _check_forbid(ctx, rel):
    for rx in ctx.forbid:
        if rx.search(rel):
            raise SystemExit("ЗАПРЕЩЁННЫЙ источник %r (display-тексты нельзя тянуть в каталоги; правило %s)" % (rel, rx.pattern))


def _files(ctx, spec):
    if "glob" in spec:
        files = sorted(glob.glob(os.path.join(ctx.data, spec["glob"]), recursive=True))
    elif "path" in spec:
        files = [os.path.join(ctx.data, spec["path"])]
    else:
        raise SystemExit("источник без path/glob: %r" % spec)
    files = [f for f in files if os.path.isfile(f)]
    rels = []
    for f in files:
        rel = os.path.relpath(f, ctx.data).replace("\\", "/")
        _check_forbid(ctx, rel)
        rels.append((f, rel))
    return rels


def _read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    for enc in ("utf-8-sig", "utf-16", "cp1251", "latin-1"):
        try:
            return b.decode(enc)
        except UnicodeDecodeError:
            continue
    return b.decode("utf-8", "replace")


def _rows_of(obj, root):
    if root and root not in ("$", ""):
        v = get_path(obj, root)
        if v is MISSING:
            return []
        obj = v
    if isinstance(obj, list):
        return list(obj)
    if isinstance(obj, dict):
        return [dict(v, _key=k) if isinstance(v, dict) else {"_key": k, "value": v} for k, v in obj.items()]
    return [obj]


def load_source(ctx, spec):
    key = json.dumps(spec, sort_keys=True)
    if key in ctx.cache:
        return ctx.cache[key]
    fmt = spec.get("format", "json")
    recs = []
    if fmt == "csharp_dict":
        recs = load_csharp_dict(ctx, spec)
        ctx.cache[key] = recs
        return recs
    for f, rel in _files(ctx, spec):
        stem = os.path.splitext(os.path.basename(f))[0]
        try:
            if fmt in ("csv", "tsv"):
                text = _read_text(f)
                delim = spec.get("delimiter") or ("\t" if fmt == "tsv" else ",")
                rows = list(csv.DictReader(text.splitlines(), delimiter=delim))
                base = rows
            elif fmt == "json":
                base = _rows_of(json.loads(_read_text(f)), spec.get("root"))
            elif fmt == "jsonl":
                base = [json.loads(l) for l in _read_text(f).splitlines() if l.strip()]
            elif fmt == "json_delimited":
                sep = spec.get("separator", "!=-=!")
                base = [json.loads(p) for p in _read_text(f).split(sep) if p.strip()]
            elif fmt == "json_file":      # один документ = одна запись (префабы)
                base = [json.loads(_read_text(f))]
            else:
                raise SystemExit("неизвестный format: %s" % fmt)
        except (json.JSONDecodeError, OSError) as e:
            log("  ! %s: %s", rel, e)
            ctx.warn["bad_file"] += 1
            continue
        for i, r in enumerate(base):
            if not isinstance(r, dict):
                r = {"value": r}
            r = dict(r)
            r["_file"], r["_stem"], r["_idx"] = rel, stem, i
            r["_ref"] = rel if fmt == "json_file" else "%s#%s[%d]" % (rel, spec.get("root", "") or "", i) if fmt in ("json",) else "%s#%d" % (rel, i)
            recs.append(r)
    if "where" in spec:
        recs = [r for r in recs if _where(spec["where"], r)]
    ctx.cache[key] = recs
    return recs


def _where(expr, rec):
    env = {}
    for k, v in rec.items():
        if re.fullmatch(r"[A-Za-z_]\w*", k):
            n = to_num(v)
            env[k] = n if (n is not MISSING and not isinstance(v, bool)) else v
    try:
        return bool(safe_eval(expr, env))
    except NameError as e:
        return False
    except Exception:
        return False


# --- C# словари тиров: Dictionary<int, List<string>> имя = new ... { { 0, new List<string> { A.staticID, ... } } }

def _cs_scan(ctx):
    if ctx.cs_classes is not None:
        return ctx.cs_classes
    classes = {}
    n_files = 0
    if ctx.src and os.path.isdir(ctx.src):
        for dp, _, fns in os.walk(ctx.src):
            for fn in fns:
                if not fn.endswith(".cs"):
                    continue
                n_files += 1
                text = _read_text(os.path.join(dp, fn))
                decls = [(m.start(), m.group(1)) for m in re.finditer(r"\bclass\s+(\w+)", text)]
                for m in re.finditer(r"\bstaticID\s*=\s*\"([^\"]*)\"", text):
                    prev = [d for d in decls if d[0] < m.start()]
                    if prev:
                        classes.setdefault(prev[-1][1], m.group(1))
    log("  C#: просканировано %d файлов, staticID у %d классов", n_files, len(classes))
    ctx.cs_classes = classes
    return classes


def _cs_block(text, start):
    """текст от '{' на позиции start до парной '}' (без учёта строк со скобками - для данных достаточно)"""
    depth, i, in_str = 0, start, False
    while i < len(text):
        c = text[i]
        if c == '"' and text[i - 1] != "\\":
            in_str = not in_str
        elif not in_str:
            if c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    return text[start:i + 1]
        i += 1
    return text[start:]


def load_csharp_dict(ctx, spec):
    fname, sym = spec["file"], spec["symbol"]
    resolve = spec.get("resolve", "staticID")
    found = None
    for dp, _, fns in os.walk(ctx.src or "."):
        if fname in fns:
            found = os.path.join(dp, fname)
            break
    if not found:
        log("  ! C# файл %s не найден в %s", fname, ctx.src)
        ctx.warn["missing_src"] += 1
        return []
    text = _read_text(found)
    m = re.search(r"\b%s\s*=\s*new\s+Dictionary<[^>]*>>?\s*\r?\n?\s*\{" % re.escape(sym), text)
    if not m:
        log("  ! символ %s не найден в %s", sym, fname)
        ctx.warn["missing_symbol"] += 1
        return []
    block = _cs_block(text, m.end() - 1)
    classes = _cs_scan(ctx)
    recs = []
    rel = os.path.relpath(found, ctx.src).replace("\\", "/")
    # записи верхнего уровня: { <key>, new List<...> { items } }
    for em in re.finditer(r"\{\s*(\w+)\s*,\s*new\s+List<[^>]*>\s*\{", block):
        sub = _cs_block(block, em.end() - 1)
        key = em.group(1)
        items = [x.strip() for x in sub.strip()[1:-1].split(",") if x.strip()]
        for idx, it in enumerate(items):
            rid, ok = it, False
            lit = re.fullmatch(r"\"([^\"]*)\"", it)
            if lit:
                rid, ok = lit.group(1), True
            elif it.endswith("." + resolve):
                cls = it[:-len(resolve) - 1].split(".")[-1]
                if cls in classes:
                    rid, ok = classes[cls], True
            recs.append({"id": rid, "group": int(key) if key.isdigit() else key, "pos": idx, "resolved": ok,
                         "expr": it, "_file": "src/" + rel, "_stem": sym, "_idx": len(recs),
                         "_ref": "src/%s:%s[%s][%d]" % (rel, sym, key, idx)})
    unres = sum(1 for r in recs if not r["resolved"])
    log("  C# %s.%s: %d записей, не разрешено %d", fname, sym, len(recs), unres)
    ctx.warn["cs_unresolved"] += unres
    return recs


# ------------------------------------------------------------------ text-guard

_SAFE_ID = re.compile(r"^[\w .:/#\-\[\]|;+()=,<>@%']{0,96}$")


def looks_like_text(s):
    s = s.strip()
    if len(s) > 96:
        return True
    if not _SAFE_ID.match(s):
        return True
    words = s.split()
    if len(words) > 4:
        return True
    if re.search(r"[.!?]\s+\w", s) or s.endswith(("!", "?")):
        return True
    return False


# ------------------------------------------------------------------ сборка каталога

def build_catalog(ctx, cat, consts):
    t0 = time.time()
    cid, kind = cat["id"], cat.get("kind", cat["id"])
    cols = cat.get("columns", {}) or {}
    joins = cat.get("joins", []) or []
    src = cat["source"]
    recs = load_source(ctx, src)
    log("[%s] источник: %d записей", cid, len(recs))
    stats = {"rows_in": len(recs), "guard_blocked": 0, "dup_ids": 0, "join_hits": {}}
    # подготовка join'ов
    jstate = []
    for j in joins:
        rrecs = load_source(ctx, j["source"])
        rkeys = [(r, eval_key(j["right"], r, {"$stem": r.get("_stem"), "$file": r.get("_file")})) for r in rrecs]
        match = j.get("match", "exact")
        index = None
        if match == "exact":
            index = defaultdict(list)
            for r, k in rkeys:
                for kk in (k if isinstance(k, list) else [k]):
                    if kk is not MISSING and kk is not None:
                        index[str(kk)].append(r)
        jstate.append({"spec": j, "rkeys": rkeys, "index": index, "hits": 0, "name": j.get("name", "join")})
    rows = []
    seen = defaultdict(int)
    for rec in recs:
        meta = {"$stem": rec.get("_stem"), "$file": rec.get("_file")}
        if "where_raw" in cat and not _where(cat["where_raw"], rec):
            continue
        rid = eval_key(cat["key"], rec, meta)
        if rid is MISSING or rid in (None, ""):
            continue
        rid = str(rid)
        meta["$id"] = rid
        row = OrderedDict()
        hidden = set()
        types = {}
        refs = [rec.get("_ref") or rec.get("_file")]

        def setcol(name, spec, val, row=row):
            t = spec.get("type", "number") if isinstance(spec, dict) else "number"
            types[name] = t
            if val is MISSING or val is None:
                val = spec.get("default", "") if isinstance(spec, dict) else ""
            if t in ("number", "int"):
                n = to_num(val) if val != "" else MISSING
                if n is MISSING or isinstance(n, bool):
                    n = "" if val == "" or n is MISSING else n
                if isinstance(n, float):
                    if isinstance(spec, dict) and "scale" in spec:
                        n = n * spec["scale"]
                    if isinstance(spec, dict) and "round" in spec:
                        n = round(n, spec["round"])
                    else:
                        n = float("%.6g" % n)
                    if n == int(n) and abs(n) < 1e15 and (t == "int" or True):
                        n = int(n) if t == "int" or float(n).is_integer() else n
                elif isinstance(n, int) and isinstance(spec, dict) and "scale" in spec:
                    n = n * spec["scale"]
                val = n
            elif t == "bool":
                n = to_num(val)
                val = bool(n) if n is not MISSING and val != "" else ""
            else:  # id / enum
                if isinstance(val, list):
                    val = "|".join(map(str, val))
                val = "" if val is None else str(val)
                if val and looks_like_text(val):
                    stats["guard_blocked"] += 1
                    val = ""
            row[name] = val
            if isinstance(spec, dict) and spec.get("hidden"):
                hidden.add(name)

        for name, spec in cols.items():
            if isinstance(spec, str):
                spec = {"path": spec}
            if "expr" in spec or "const" in spec:
                continue
            p = spec.get("path", name)
            v = eval_pipe(p, rec, meta)
            if isinstance(v, list) or "array" in spec:
                v = reduce_array(v, spec.get("array", "first"))
            setcol(name, spec, v)
        # joins
        for js in jstate:
            j = js["spec"]
            lkeys = j["on"] if isinstance(j["on"], list) else [j["on"]]
            lv = []
            for lk in lkeys:
                k = eval_key(lk, rec, meta)
                lv.extend(k if isinstance(k, list) else [k])
            lv = [str(x) for x in lv if x is not MISSING and x not in (None, "")]
            matched = []
            if js["index"] is not None:
                for k in lv:
                    matched.extend(js["index"].get(k, []))
            else:
                mode = js["spec"]["match"]
                for r, rk in js["rkeys"]:
                    rks = [str(x) for x in (rk if isinstance(rk, list) else [rk]) if x is not MISSING and x not in (None, "")]
                    ok = False
                    for a in lv:
                        for b in rks:
                            if (mode == "contains_right" and b and b in a) or (mode == "contains_left" and a and a in b) \
                                    or (mode == "startswith_right" and b and a.startswith(b)) \
                                    or (mode == "startswith_left" and a and b.startswith(a)):
                                ok = True
                                break
                        if ok:
                            break
                    if ok:
                        matched.append(r)
            if "where" in j:
                matched = [r for r in matched if _where(j["where"], r)]
            seen_ids, uniq = set(), []
            for r in matched:
                if id(r) not in seen_ids:
                    seen_ids.add(id(r))
                    uniq.append(r)
            matched = uniq
            if matched:
                js["hits"] += 1
                refs.extend((r.get("_ref") or r.get("_file")) for r in matched[:2])
            for cname, cspec in (j.get("columns") or {}).items():
                if isinstance(cspec, str):
                    cspec = {"field": cspec}
                agg = cspec.get("agg", "first")
                if agg == "count":
                    v = len(matched)
                elif not matched:
                    v = MISSING
                else:
                    vals = []
                    for r in matched:
                        x = eval_pipe(cspec["field"], r, {"$stem": r.get("_stem"), "$file": r.get("_file")}) if "field" in cspec else MISSING
                        if isinstance(x, list):
                            x = reduce_array(x, cspec.get("array", "first"))
                        if x is not MISSING and x not in (None, ""):
                            vals.append(x)
                    v = reduce_array(vals, agg) if vals else MISSING
                if v is MISSING and agg != "count" and "default" not in cspec:
                    v = ""
                setcol(cname, cspec, v)
        # вычисляемые
        env_consts = dict(consts)
        for name, spec in cols.items():
            if isinstance(spec, dict) and ("expr" in spec or "const" in spec):
                if "const" in spec:
                    setcol(name, spec, spec["const"])
                    continue
                env = dict(env_consts)
                for k, v in row.items():
                    if re.fullmatch(r"[A-Za-z_]\w*", k):
                        env[k] = v
                env["id"] = rid
                try:
                    v = safe_eval(spec["expr"], env)
                except Exception:
                    v = MISSING
                setcol(name, spec, v)
        row["__hidden"] = hidden
        row["__types"] = types
        if "where" in cat:
            env = dict(consts)
            env.update({k: v for k, v in row.items() if not k.startswith("__") and re.fullmatch(r"[A-Za-z_]\w*", k)})
            env["id"] = rid
            try:
                if not safe_eval(cat["where"], env):
                    continue
            except Exception:
                continue
        seen[rid] += 1
        out_id = rid if seen[rid] == 1 else "%s#%d" % (rid, seen[rid])
        if seen[rid] > 1:
            stats["dup_ids"] += 1
        rows.append({"id": out_id, "row": row, "refs": [r for r in refs if r]})
    for js in jstate:
        stats["join_hits"][js["name"]] = "%d/%d" % (js["hits"], len(rows))
    # группировка
    if "group" in cat:
        rows = group_rows(rows, cat["group"])
        stats["grouped"] = True
    if "sort" in cat:
        keys = cat["sort"] if isinstance(cat["sort"], list) else [cat["sort"]]
        for k in reversed(keys):
            desc = k.startswith("-")
            k = k.lstrip("-")
            rows.sort(key=lambda r: (r["row"].get(k, "") == "", r["row"].get(k, 0) if isinstance(r["row"].get(k, 0), (int, float)) else str(r["row"].get(k))), reverse=desc)
    stats["rows"] = len(rows)
    stats["seconds"] = round(time.time() - t0, 2)
    return rows, stats


def group_rows(rows, g):
    by = g["by"] if isinstance(g["by"], list) else [g["by"]]
    buckets = OrderedDict()
    for r in rows:
        k = tuple(str(r["row"].get(b, "")) for b in by)
        buckets.setdefault(k, []).append(r)
    out = []
    for k, lst in buckets.items():
        row = OrderedDict()
        types = {}
        for b, v in zip(by, k):
            row[b] = lst[0]["row"].get(b, v)
            types[b] = lst[0]["row"]["__types"].get(b, "id")
        for name, spec in (g.get("aggs") or {}).items():
            fn = spec.get("fn", "count")
            fld = spec.get("field")
            if fn == "count":
                v = len(lst)
            else:
                v = reduce_array([x["row"].get(fld, "") for x in lst if x["row"].get(fld, "") != ""], fn)
                if v is MISSING:
                    v = ""
            if isinstance(v, float):
                v = round(v, spec.get("round", 4))
            row[name] = v
            types[name] = spec.get("type", "number")
        row["__hidden"] = set()
        row["__types"] = types
        out.append({"id": "|".join(k), "row": row, "refs": lst[0]["refs"][:1]})
    return out


# ------------------------------------------------------------------ вывод

def safe_name(s):
    s = re.sub(r"[^\w.\-]+", "_", s)
    return s[:120] or "_"


def write_outputs(out, cat, rows, stats, args):
    cid, kind = cat["id"], cat.get("kind", cat["id"])
    os.makedirs(out, exist_ok=True)
    cols = []
    for r in rows:
        for k in r["row"]:
            if not k.startswith("__") and k not in r["row"]["__hidden"] and k not in cols:
                cols.append(k)
    header = ["id", "kind"] + cols + ["source_ref"]
    with open(os.path.join(out, cid + ".csv"), "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f, lineterminator="\n")
        w.writerow(header)
        for r in rows:
            w.writerow([r["id"], kind] + [("" if r["row"].get(c) is None else r["row"].get(c, "")) for c in cols] + [r["refs"][0] if r["refs"] else ""])
    # markdown
    md_max = cat.get("md_max_rows", 3000)
    with open(os.path.join(out, cid + ".md"), "w", encoding="utf-8", newline="\n") as f:
        f.write("# %s (%s)\n\nСтрок: %d. Только id и числа; источник каждой строки - в колонке source_ref (и в YAML-записях).\n\n" % (cid, kind, len(rows)))
        f.write("| " + " | ".join(header) + " |\n|" + "|".join(["---"] * len(header)) + "|\n")
        for r in rows[:md_max]:
            vals = [r["id"], kind] + [str(r["row"].get(c, "")) for c in cols] + [r["refs"][0] if r["refs"] else ""]
            f.write("| " + " | ".join(v.replace("|", "\\|") for v in vals) + " |\n")
        if len(rows) > md_max:
            f.write("\n_... усечено до %d строк, полный набор в %s.csv_\n" % (md_max, cid))
    # yaml-записи
    mode = cat.get("records", "auto")
    if mode == "auto":
        mode = "per_row" if len(rows) <= args.per_row_limit else "per_catalog"
    recs = []
    for r in rows:
        nums, attrs = OrderedDict(), OrderedDict()
        for c in cols:
            v = r["row"].get(c, "")
            if v == "" or v is None:
                continue
            (nums if r["row"]["__types"].get(c, "number") in ("number", "int") else attrs)[c] = v
        rec = OrderedDict(id=r["id"], kind=kind, numbers=nums)
        if attrs:
            rec["attrs"] = attrs
        rec["source_ref"] = r["refs"][0] if r["refs"] else ""
        if len(r["refs"]) > 1:
            rec["joined_refs"] = r["refs"][1:]
        recs.append(rec)
    dump = lambda o: yaml.safe_dump(o, allow_unicode=True, sort_keys=False, default_flow_style=False)  # noqa
    if mode == "per_row":
        d = os.path.join(out, "records", cid)
        os.makedirs(d, exist_ok=True)
        names = defaultdict(int)
        for rec in recs:
            n = safe_name(rec["id"])
            names[n.lower()] += 1
            if names[n.lower()] > 1:
                n += "~%d" % names[n.lower()]
            with open(os.path.join(d, n + ".yaml"), "w", encoding="utf-8", newline="\n") as f:
                f.write(dump(rec))
    elif mode == "per_catalog":
        with open(os.path.join(out, "records", cid + ".records.yaml"), "w", encoding="utf-8", newline="\n") \
                if os.makedirs(os.path.join(out, "records"), exist_ok=True) is None else None as f:
            f.write(dump(recs))
    return {"columns": cols, "records_mode": mode}


def main():
    ap = argparse.ArgumentParser(description="Генератор каталогов (id + числа) по YAML-правилам")
    ap.add_argument("--data", required=True, help="<ref_dir>/data (вывод unity_extract)")
    ap.add_argument("--rules", required=True, help="rules.yaml")
    ap.add_argument("--out", required=True, help="каталог вывода")
    ap.add_argument("--src", default=None, help="<ref_dir>/src (декомпилят; по умолчанию <data>/../src)")
    ap.add_argument("--only", default="", help="через запятую: id каталогов")
    ap.add_argument("--per-row-limit", type=int, default=2500, help="больше строк - YAML одним файлом на каталог")
    args = ap.parse_args()
    t0 = time.time()
    data = os.path.abspath(args.data)
    src = os.path.abspath(args.src) if args.src else os.path.join(os.path.dirname(data), "src")
    with open(args.rules, encoding="utf-8") as f:
        rules = yaml.safe_load(f)
    forbid = rules.get("forbid_sources", [r"itemsinfo", r"skillsinfo", r"outfitsinfo", r"uitexts", r"dialog", r"speakers", r"/ui/[^/]*info"])
    ctx = Ctx(data, src, forbid)
    consts = {}
    for k, v in (rules.get("consts") or {}).items():
        consts[k] = v["value"] if isinstance(v, dict) else v
    only = set(x for x in args.only.split(",") if x)
    index = []
    for cat in rules["catalogs"]:
        if only and cat["id"] not in only:
            continue
        try:
            rows, stats = build_catalog(ctx, cat, consts)
        except SystemExit:
            raise
        except Exception as e:  # noqa
            import traceback
            traceback.print_exc()
            log("[%s] ОШИБКА: %s", cat["id"], e)
            index.append({"id": cat["id"], "error": str(e)})
            continue
        info = write_outputs(args.out, cat, rows, stats, args)
        index.append(dict(id=cat["id"], kind=cat.get("kind", cat["id"]), **stats, **info))
        log("[%s] строк %d, колонок %d, join: %s, guard: %d, записи: %s", cat["id"], stats["rows"], len(info["columns"]),
            stats["join_hits"], stats["guard_blocked"], info["records_mode"])
    with open(os.path.join(args.out, "_catalogs.yaml"), "w", encoding="utf-8", newline="\n") as f:
        yaml.safe_dump({"generator": "make_catalog %s" % VERSION, "data": data, "rules": os.path.abspath(args.rules),
                        "warnings": dict(ctx.warn), "catalogs": index}, f, allow_unicode=True, sort_keys=False)
    log("ГОТОВО: %d каталогов за %.1f c -> %s", len(index), time.time() - t0, args.out)


if __name__ == "__main__":
    main()

input.content:
# Правила каталогов для Wizard of Legend (WoL). Вход: <ref_dir>/data (вывод unity_extract), <ref_dir>/src (декомпилят).
# Каталоги содержат ТОЛЬКО id и числа. Имена/описания пишутся потом вручную своими словами.
#
# Запуск (из папки reverse-kit/catalog):
#   .venv\Scripts\python.exe -I make_catalog.py --data C:\visual projects\wol-ref-kit-test\data ^
#       --rules rules\wol.yaml --out C:\visual projects\wol-catalog
version: 1

# Источники с display-текстами читать нельзя (имена/описания предметов, диалоги, интерфейс).
forbid_sources:
  - 'itemsinfo'
  - 'skillsinfo'
  - 'outfitsinfo'
  - 'uitexts'
  - 'dialog'
  - 'speakers'
  - '/ui/[^/]*info'

# Константы, взятые из кода (с указанием места). Используются в expr.
consts:
  gold_price_mult:        {value: 25, ref: "src/LootManager.cs GetPrice: GetBasePrice(id) * 25"}
  relic_plat_tier_mult:   {value: 4,  ref: "src/LootManager.cs GetPlatPrice: (GetItemTier(id) + 1) * 4"}
  arcana_plat_tier_mult:  {value: 5,  ref: "src/LootManager.cs GetPlatPrice: Clamp(GetSkillTier(id), 1, 4) * 5"}
  default_base_price:     {value: 1,  ref: "src/LootManager.cs GetBasePrice: нет в PriceDict -> 1"}

catalogs:

# ------------------------------------------------------------------ заклинания игрока
# skills.json (статы) + префаб снаряда/эффекта (размер хитбокса) + длины анимаций + тир арканы из кода
- id: spells
  kind: spell
  source: {path: text/assets/data/player/skills.json, format: json, root: skillStats}
  key: "ID[0]"
  columns:
    element:            {path: "elementType[0]", type: enum}
    targets:            {path: "targetNames", array: join, type: enum}
    damage:             "damage[0]"
    damage_alt:         {path: "damage[1]"}
    cooldown:           "cooldown[0]"
    knockback:          "knockbackMultiplier[0]"
    knockback_alt:      {path: "knockbackMultiplier[1]"}
    hitstun_mult:       "hitStunDurationModifier[0]"
    same_attack_immunity_s: "sameAttackImmunityTime[0]"
    same_target_immunity_s: "sameTargetImmunityTime[0]"
    overdrive_mult:     "overdriveProgressMultiplier[0]"
    burn_chance:        "burnChance[0]"
    burn_level:         "burnLevel[0]"
    shock_chance:       "shockChance[0]"
    shock_level:        "shockLevel[0]"
    freeze_chance:      "freezeChance[0]"
    freeze_duration_s:  "freezeDuration[0]"
    slow_chance:        "slowChance[0]"
    slow_level:         "slowLevel[0]"
    poison_chance:      "poisonChance[0]"
    poison_level:       "poisonLevel[0]"
    root_chance:        "rootChance[0]"
    root_duration_s:    "rootDuration[0]"
    chaos_chance:       "chaosChance[0]"
    duration_s:         "duration[0]"
    damage_interval_s:  "damageInterval[0]"
    spawn_count:        "spawnCount[0]"
    base_health:        "baseHealth[0]"
    dps_est:            {expr: "damage / cooldown if cooldown else ''"}
  joins:
    # префаб снаряда: имя префаба (lower) входит в id (lower) заклинания
    - name: prefab
      source: {glob: "prefabs/assets/prefabs/playerskills/*.json", format: json_file}
      right: "$stem | lower"
      on: "$id | lower"
      match: contains_right
      columns:
        prefab:      {field: "path | stem", type: id}
    # хитбокс снаряда: максимальный размер коллайдера-триггера префаба
    - name: collider
      source: {path: extra/colliders.csv, format: csv, where: "is_trigger == True"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: contains_right
      where: "contains(prefab, '/playerskills/')"
      columns:
        hit_w_m:     {field: world_size_x, agg: max}
        hit_h_m:     {field: world_size_y, agg: max}
        hit_shapes:  {agg: count}
    # длины анимаций префаба: контроллер, чей owner = этот префаб
    - name: anim
      source: {path: extra/anim_clips.csv, format: csv}
      right: "owner_prefabs | split:; | stem | lower"
      on: "$id | lower"
      match: contains_right
      where: "contains(owner_prefabs, '/playerskills/')"
      columns:
        anim_len_max_s: {field: effective_length_s, agg: max}
        anim_states:    {agg: count}
    # тир арканы (в коде: LootManager.skillTierDict)
    - name: tier
      source: {format: csharp_dict, file: LootManager.cs, symbol: skillTierDict, resolve: staticID}
      right: "id | lower"
      on: "$id | lower"
      match: exact
      columns:
        arcana_tier: {field: group, agg: first}

# ------------------------------------------------------------------ скиллы врагов (сырьё для enemies/bosses)
- id: enemy_skills
  kind: enemy_skill
  source: {path: text/assets/data/enemy/skills.json, format: json, root: skillStats}
  key: "ID[0]"
  columns:
    element:           {path: "elementType[0]", type: enum}
    targets:           {path: "targetNames", array: join, type: enum}
    damage:            "damage[0]"
    knockback:         "knockbackMultiplier[0]"
    hitstun_mult:      "hitStunDurationModifier[0]"
    same_attack_immunity_s: "sameAttackImmunityTime[0]"
    same_target_immunity_s: "sameTargetImmunityTime[0]"
    crit_chance:       "criticalHitChance[0]"
    crit_damage_mult:  "criticalDamageModifier[0]"
    burn_chance:       "burnChance[0]"
    freeze_chance:     "freezeChance[0]"
    freeze_duration_s: "freezeDuration[0]"
    shock_chance:      "shockChance[0]"
    slow_chance:       "slowChance[0]"
    poison_chance:     "poisonChance[0]"
    duration_s:        "duration[0]"

# ------------------------------------------------------------------ враги
# статы из префаба + скиллы (по префиксу id) + хитбокс + длины анимаций
- id: enemies
  kind: enemy
  source: {glob: "prefabs/assets/prefabs/enemies/*.json", format: json_file}
  key: "$stem"
  columns:
    max_health:        {path: "objects[0].components[?class==Health].fields.healthStat", array: first}
    armor:             {path: "objects[0].components[?class==Health].fields.armorStat"}
    evade:             {path: "objects[0].components[?class==Health].fields.evadeStat"}
    damage_taken_mult: {path: "objects[0].components[?class==Health].fields.damageTakenStat"}
    move_speed:        {path: "objects[0].components[?class==Movement].fields.moveSpeedStat"}
    dash_speed:        {path: "objects[0].components[?class==Movement].fields.dashSpeedStat"}
    dash_duration_s:   {path: "objects[0].components[?class==Movement].fields.dashDurationStat"}
    alert_radius:      {path: "objects[0].components[*].fields.alertRadius"}
    escape_radius:     {path: "objects[0].components[*].fields.escapeRadius"}
    attack_radius:     {path: "objects[0].components[*].fields.attackRadius"}
    surround_radius:   {path: "objects[0].components[*].fields.surroundRadius"}
    alert_nearby_radius: {path: "objects[0].components[*].fields.alertNearbyEnemiesRadius"}
    hitstun_mult:      {path: "objects[0].components[*].fields.hitStunDurationModifier"}
    element_id:        {path: "objects[0].components[*].fields.element", type: enum}
    mass:              {path: "objects[0].components[?class==Rigidbody2D].fields.m_Mass"}
    linear_drag:       {path: "objects[0].components[?class==Rigidbody2D].fields.m_LinearDrag"}
    n_components:      {path: "objects[0].components", array: len}
    ehp_vs_dps10:      {expr: "max_health / 10 if max_health != '' else ''"}
  joins:
    - name: skills
      source: {path: text/assets/data/enemy/skills.json, format: json, root: skillStats}
      right: "ID[0] | lower"
      on: ["$id", "neutral{$id}"]
      match: startswith_left
      columns:
        skill_count:     {agg: count}
        skill_dmg_max:   {field: "damage[0]", agg: max}
        skill_dmg_sum:   {field: "damage[0]", agg: sum}
        skill_kb_max:    {field: "knockbackMultiplier[0]", agg: max}
    - name: collider
      source: {path: extra/colliders.csv, format: csv}
      right: "prefab"
      on: "path"
      match: exact
      where: "endswith(gameobject, 'HurtBox') or endswith(gameobject, 'Hurtbox')"
      columns:
        hurtbox_w_m:     {field: world_size_x, agg: max}
        hurtbox_h_m:     {field: world_size_y, agg: max}
    - name: anim
      source: {path: extra/anim_clips.csv, format: csv}
      right: "owner_prefabs | split:;"
      on: "path"
      match: exact
      columns:
        anim_states:     {agg: count}
        longest_state_s: {field: effective_length_s, agg: max}
    - name: attack_anim
      source: {path: extra/anim_clips.csv, format: csv, where: "re('(?i)attack|windup|lunge|slam|slash|throw|cast|shoot|charge|spin|stab|fire|smash', state)"}
      right: "owner_prefabs | split:;"
      on: "path"
      match: exact
      columns:
        attack_states:      {agg: count}
        attack_anim_max_s:  {field: effective_length_s, agg: max}
        attack_anim_min_s:  {field: effective_length_s, agg: min}

# ------------------------------------------------------------------ боссы
- id: bosses
  kind: boss
  source: {glob: "prefabs/assets/prefabs/bosses/*.json", format: json_file}
  key: "$stem"
  columns:
    max_health:        {path: "objects[0].components[?class==Health].fields.healthStat"}
    armor:             {path: "objects[0].components[?class==Health].fields.armorStat"}
    evade:             {path: "objects[0].components[?class==Health].fields.evadeStat"}
    move_speed:        {path: "objects[0].components[?class==Movement].fields.moveSpeedStat"}
    dash_speed:        {path: "objects[0].components[?class==Movement].fields.dashSpeedStat"}
    dash_duration_s:   {path: "objects[0].components[?class==Movement].fields.dashDurationStat"}
    alert_radius:      {path: "objects[0].components[*].fields.alertRadius"}
    attack_radius:     {path: "objects[0].components[*].fields.attackRadius"}
    hitstun_mult:      {path: "objects[0].components[*].fields.hitStunDurationModifier"}
    element_id:        {path: "objects[0].components[*].fields.element", type: enum}
    mass:              {path: "objects[0].components[?class==Rigidbody2D].fields.m_Mass"}
  joins:
    - name: skills
      source: {path: text/assets/data/enemy/skills.json, format: json, root: skillStats}
      right: "ID[0] | lower"
      on: "$id"
      match: startswith_left
      columns:
        skill_count:     {agg: count}
        skill_dmg_max:   {field: "damage[0]", agg: max}
        skill_dmg_sum:   {field: "damage[0]", agg: sum}
    - name: anim
      source: {path: extra/anim_clips.csv, format: csv}
      right: "owner_prefabs | split:;"
      on: "path"
      match: exact
      columns:
        anim_states:     {agg: count}
        longest_state_s: {field: effective_length_s, agg: max}

# ------------------------------------------------------------------ реликвии: тиры и цены
# тир = ключ в LootManager.itemTierDict (код), базовая цена = storeprices.json, формулы цен - в consts
- id: relics
  kind: relic
  source: {format: csharp_dict, file: LootManager.cs, symbol: itemTierDict, resolve: staticID}
  key: "id"
  where: "resolved_flag == 1"
  columns:
    resolved_flag: {path: "resolved", type: int, hidden: true}
    tier:          {path: "group", type: int}
    pos_in_tier:   {path: "pos", type: int}
    base_price:    {const: 0, hidden: true}
  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first}
  # вычисляемые (после join'ов)
- id: relic_prices
  kind: relic_price
  source: {format: csharp_dict, file: LootManager.cs, symbol: itemTierDict, resolve: staticID}
  key: "id"
  where: "resolved_flag == 1"
  columns:
    resolved_flag: {path: "resolved", type: int, hidden: true}
    tier:          {path: "group", type: int}
  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first, type: int, hidden: true}
  # цены считаются отдельными колонками ниже
  # (expr-колонки вычисляются после join'ов независимо от порядка в YAML)
  # base = listed_price или default_base_price (нет в словаре -> 1)
  # gold = base * 25; plat = base + (tier + 1) * 4
  # NB: expr-колонки перечислены в `columns`; для ясности вынесены в отдельный блок ниже.

# ------------------------------------------------------------------ арканы: тиры и цены
- id: arcana_tiers
  kind: arcana_tier
  source: {format: csharp_dict, file: LootManager.cs, symbol: skillTierDict, resolve: staticID}
  key: "id"
  where: "resolved_flag == 1"
  columns:
    resolved_flag: {path: "resolved", type: int, hidden: true}
    tier:          {path: "group", type: int}
  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first, type: int, hidden: true}

# ------------------------------------------------------------------ цены магазина (сырые)
- id: store_prices
  kind: store_price
  source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
  key: "name"
  columns:
    base_price:  {path: "price", type: int}
    gold_price:  {expr: "base_price * gold_price_mult", type: int}
  joins:
    - name: itier
      source: {format: csharp_dict, file: LootManager.cs, symbol: itemTierDict, resolve: staticID}
      right: "id"
      on: "$id"
      match: exact
      columns:
        relic_tier: {field: group, agg: first, type: int}
    - name: stier
      source: {format: csharp_dict, file: LootManager.cs, symbol: skillTierDict, resolve: staticID}
      right: "id"
      on: "$id"
      match: exact
      columns:
        arcana_tier: {field: group, agg: first, type: int}

# ------------------------------------------------------------------ комнаты
- id: rooms
  kind: room
  source: {path: text/assets/data/rooms/roomdb.json, format: json_delimited, separator: "!=-=!"}
  key: "name"
  columns:
    type_id:        {path: type, type: int}
    width:          {path: width, type: int}
    height:         {path: height, type: int}
    area:           {expr: "width * height", type: int}
    element_id:     {path: element, type: int}
    optional_conn_mask: {path: optionalConnections, type: int}
    required_conn_mask: {path: requiredConnections, type: int}
  joins:
    - name: prefab
      source: {path: prefabs/_index.csv, format: csv, where: "contains(path, '/rooms/prefabs/')"}
      right: "path | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        prefab_objects:    {field: n_objects, agg: first, type: int}
        prefab_components: {field: n_components, agg: first, type: int}
    - name: colliders
      source: {path: extra/colliders.csv, format: csv, where: "contains(prefab, '/rooms/prefabs/')"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        n_colliders:      {agg: count}
        n_trigger_colliders: {field: is_trigger, agg: sum}
    - name: lights
      source: {path: extra/lights.csv, format: csv, where: "contains(prefab, '/rooms/prefabs/')"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        n_lights: {agg: count}
    - name: ui
      source: {path: extra/ui_elements.csv, format: csv, where: "contains(prefab, '/rooms/prefabs/')"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        n_ui_elements: {agg: count}

# ------------------------------------------------------------------ дроп-таблицы (числа)
- id: loot_tables
  kind: loot_table
  source: {path: text/assets/data/loot/loottable.json, format: json, root: dropTableEntries}
  key: "name"
  columns:
    min_soul: {path: minSoul}
    max_soul: {path: maxSoul}
    gold_rate: {path: goldDropRate}
    min_gold: {path: minGold}
    max_gold: {path: maxGold}
    plat_rate: {path: platDropRate}
    min_plat: {path: minPlat}
    max_plat: {path: maxPlat}
    health_rate: {path: healthDropRate}
    min_health: {path: minHealth}
    max_health: {path: maxHealth}
    item_rate: {path: itemDropRate}
    skill_rate: {path: skillDropRate}
    locked_skill_rate: {path: lockedSkillDropRate}
    signature_skill_rate: {path: signatureSkillDropRate}
    n_item_drop_list: {path: itemDropList, array: len}
    n_skill_drop_list: {path: skillDropList, array: len}

# ------------------------------------------------------------------ кривые значений (value_curves)
- id: curves
  kind: curve
  records: per_catalog
  md_max_rows: 1500
  source: {path: extra/curves.json, format: json, root: curves}
  key: "{owner | stem}#{go}{clip}#{field}"
  columns:
    source_kind:  {path: source, type: enum}
    target_path:  {path: target_path, type: id}
    target_type:  {path: target_type, type: enum}
    n_keys:       {path: keys, array: len}
    t_end_s:      {path: "keys[-1][0]"}
    v_first:      {path: "keys[0][1]"}
    v_last:       {path: "keys[-1][1]"}
    v_min:        {path: "keys[*][1]", array: min}
    v_max:        {path: "keys[*][1]", array: max}
    pre_wrap:     {path: preWrap, type: int}
    post_wrap:    {path: postWrap, type: int}
- id: curves_by_owner
  kind: curve_owner
  source: {path: extra/curves.json, format: json, root: curves}
  key: "owner"
  columns:
    is_mono:      {const: 0, hidden: true}
  # агрегат по владельцу строится из каталога curves (ниже group), поэтому group задаётся на сырых строках
  group:
    by: [id]
    aggs:
      n_curves: {fn: count}

# ------------------------------------------------------------------ инвентарь ассетов (метаданные)
- id: asset_inventory
  kind: asset_inventory
  records: per_catalog
  md_max_rows: 2500
  source: {path: extra/asset_inventory_summary.csv, format: csv}
  key: "{group}::{type}"
  columns:
    group_path: {path: group, type: id}
    asset_type: {path: type, type: enum}
    count:      {path: count, type: int}
- id: asset_inventory_by_type
  kind: asset_type
  source: {path: extra/asset_inventory_summary.csv, format: csv, where: "group == '(all)'"}
  key: "type"
  columns:
    count:      {path: count, type: int}

# ------------------------------------------------------------------ новые коллекции (метаданные)
- id: vfx_emitters
  kind: vfx_emitter
  records: per_catalog
  source: {path: extra/vfx_particles.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    emitter_kind:    {path: kind, type: enum}
    duration_s:      {path: duration_s}
    looping:         {path: looping, type: bool}
    start_lifetime_s: {path: start_lifetime}
    start_speed:     {path: start_speed}
    start_size:      {path: start_size}
    gravity:         {path: gravity_modifier}
    max_particles:   {path: max_particles, type: int}
    rate_per_s:      {path: emission_rate}
    burst_total_min: {path: burst_total_min, type: int}
    shape_type:      {path: shape_type, type: enum}
    shape_radius:    {path: shape_radius}
    modules:         {path: modules_enabled, type: enum}
    sort_order:      {path: sort_order, type: int}
    est_particles_per_cycle: {expr: "burst_total_min + (rate_per_s * duration_s if rate_per_s != '' and duration_s != '' else 0)"}

- id: lights
  kind: light
  records: per_catalog
  source: {path: extra/lights.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    light_type_id: {path: light_type, type: enum}
    color_r: {path: color_r}
    color_g: {path: color_g}
    color_b: {path: color_b}
    intensity: {path: intensity}
    range_m: {path: range}
    spot_angle: {path: spot_angle}
    shadows_id: {path: shadows, type: enum}
    has_animator: {path: has_animator, type: bool}

- id: audio_clips
  kind: audio_clip
  records: per_catalog
  source: {path: extra/audio_clips.csv, format: csv}
  key: "container_path | stem"
  columns:
    group_path: {path: group, type: id}
    length_s:   {path: length_s}
    frequency_hz: {path: frequency, type: int}
    channels:   {path: channels, type: int}
    bits:       {path: bits, type: int}
    load_type_id: {path: load_type, type: enum}
    compression_id: {path: compression, type: enum}

- id: ui_canvases
  kind: ui_canvas
  source: {path: extra/ui_canvases.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    render_mode: {path: render_mode, type: enum}
    sort_order: {path: sort_order, type: int}
    plane_distance: {path: plane_distance}
    ref_res_x: {path: ref_res_x}
    ref_res_y: {path: ref_res_y}
    ref_ppu: {path: ref_ppu}

- id: ui_elements
  kind: ui_element
  records: per_catalog
  md_max_rows: 1500
  source: {path: extra/ui_elements.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    kinds: {path: kinds, type: enum}
    depth: {path: depth, type: int}
    anchor_min_x: {path: anchor_min_x}
    anchor_min_y: {path: anchor_min_y}
    anchor_max_x: {path: anchor_max_x}
    anchor_max_y: {path: anchor_max_y}
    size_x: {path: size_x}
    size_y: {path: size_y}
    pos_x: {path: pos_x}
    pos_y: {path: pos_y}
    n_children: {path: n_children, type: int}

- id: input_actions
  kind: input_action
  source: {path: extra/input_actions.csv, format: csv}
  key: "name"
  columns:
    action_id: {path: action_id, type: int}
    type_id:   {path: type, type: enum}
    user_assignable: {path: user_assignable, type: bool}
  joins:
    - name: bindings
      source: {path: extra/input_default_bindings.csv, format: csv}
      right: "action_name"
      on: "$id"
      match: exact
      columns:
        n_default_bindings: {agg: count}

- id: input_default_bindings
  kind: input_binding
  source: {path: extra/input_default_bindings.csv, format: csv}
  key: "{map_kind}/{action_name}/{element_type}-{element_identifier_id}-{key_code}-{axis_contribution}"
  columns:
    map_kind_id:  {path: map_kind, type: enum}
    element_type: {path: element_type, type: enum}
    element_identifier_id: {path: element_identifier_id, type: int}
    axis_range:   {path: axis_range, type: enum}
    axis_contribution: {path: axis_contribution, type: enum}
    key_code:     {path: key_code, type: int}

- id: tilesets
  kind: tileset
  source: {path: extra/tiled_tilesets.csv, format: csv}
  key: "name"
  columns:
    tile_w: {path: tile_w, type: int}
    tile_h: {path: tile_h, type: int}
    image_w: {path: image_w, type: int}
    image_h: {path: image_h, type: int}
    columns: {path: columns, type: int}
    tile_count: {path: tile_count, type: int}

- id: tilemaps
  kind: tilemap
  records: per_catalog
  source: {path: extra/tiled_maps.csv, format: csv}
  key: "path | stem"
  columns:
    width: {path: width, type: int}
    height: {path: height, type: int}
    n_layers: {path: n_layers, type: int}
    n_tilesets: {path: n_tilesets, type: int}
    n_nonempty_tiles: {path: n_nonempty_tiles, type: int}
    fill_ratio: {expr: "n_nonempty_tiles / (width * height * n_layers) if width and height and n_layers else ''"}

- id: decor_variants
  kind: decor_variant
  records: per_catalog
  md_max_rows: 1500
  source: {path: extra/decor_variants.csv, format: csv}
  key: "{prefab | stem}/{go}/{field}"
  columns:
    decor_class: {path: class, type: enum}
    n_items: {path: n_items, type: int}
    n_distinct: {path: n_distinct, type: int}

toolu_01M4jJRjms9GPGhXVq9AnmFb.content:
# Правила каталогов для Wizard of Legend (WoL). Вход: <ref_dir>/data (вывод unity_extract), <ref_dir>/src (декомпилят).
# Каталоги содержат ТОЛЬКО id и числа. Имена/описания пишутся потом вручную своими словами.
#
# Запуск (из папки reverse-kit/catalog):
#   .venv\Scripts\python.exe -I make_catalog.py --data C:\visual projects\wol-ref-kit-test\data ^
#       --rules rules\wol.yaml --out C:\visual projects\wol-catalog
version: 1

# Источники с display-текстами читать нельзя (имена/описания предметов, диалоги, интерфейс).
forbid_sources:
  - 'itemsinfo'
  - 'skillsinfo'
  - 'outfitsinfo'
  - 'uitexts'
  - 'dialog'
  - 'speakers'
  - '/ui/[^/]*info'

# Константы, взятые из кода (с указанием места). Используются в expr.
consts:
  gold_price_mult:        {value: 25, ref: "src/LootManager.cs GetPrice: GetBasePrice(id) * 25"}
  relic_plat_tier_mult:   {value: 4,  ref: "src/LootManager.cs GetPlatPrice: (GetItemTier(id) + 1) * 4"}
  arcana_plat_tier_mult:  {value: 5,  ref: "src/LootManager.cs GetPlatPrice: Clamp(GetSkillTier(id), 1, 4) * 5"}
  default_base_price:     {value: 1,  ref: "src/LootManager.cs GetBasePrice: нет в PriceDict -> 1"}

catalogs:

# ------------------------------------------------------------------ заклинания игрока
# skills.json (статы) + префаб снаряда/эффекта (размер хитбокса) + длины анимаций + тир арканы из кода
- id: spells
  kind: spell
  source: {path: text/assets/data/player/skills.json, format: json, root: skillStats}
  key: "ID[0]"
  columns:
    element:            {path: "elementType[0]", type: enum}
    targets:            {path: "targetNames", array: join, type: enum}
    damage:             "damage[0]"
    damage_alt:         {path: "damage[1]"}
    cooldown:           "cooldown[0]"
    knockback:          "knockbackMultiplier[0]"
    knockback_alt:      {path: "knockbackMultiplier[1]"}
    hitstun_mult:       "hitStunDurationModifier[0]"
    same_attack_immunity_s: "sameAttackImmunityTime[0]"
    same_target_immunity_s: "sameTargetImmunityTime[0]"
    overdrive_mult:     "overdriveProgressMultiplier[0]"
    burn_chance:        "burnChance[0]"
    burn_level:         "burnLevel[0]"
    shock_chance:       "shockChance[0]"
    shock_level:        "shockLevel[0]"
    freeze_chance:      "freezeChance[0]"
    freeze_duration_s:  "freezeDuration[0]"
    slow_chance:        "slowChance[0]"
    slow_level:         "slowLevel[0]"
    poison_chance:      "poisonChance[0]"
    poison_level:       "poisonLevel[0]"
    root_chance:        "rootChance[0]"
    root_duration_s:    "rootDuration[0]"
    chaos_chance:       "chaosChance[0]"
    duration_s:         "duration[0]"
    damage_interval_s:  "damageInterval[0]"
    spawn_count:        "spawnCount[0]"
    base_health:        "baseHealth[0]"
    dps_est:            {expr: "damage / cooldown if cooldown else ''"}
  joins:
    # префаб снаряда: имя префаба (lower) входит в id (lower) заклинания
    - name: prefab
      source: {glob: "prefabs/assets/prefabs/playerskills/*.json", format: json_file}
      right: "$stem | lower"
      on: "$id | lower"
      match: contains_right
      columns:
        prefab:      {field: "path | stem", type: id}
    # хитбокс снаряда: максимальный размер коллайдера-триггера префаба
    - name: collider
      source: {path: extra/colliders.csv, format: csv, where: "is_trigger == True"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: contains_right
      where: "contains(prefab, '/playerskills/')"
      columns:
        hit_w_m:     {field: world_size_x, agg: max}
        hit_h_m:     {field: world_size_y, agg: max}
        hit_shapes:  {agg: count}
    # длины анимаций префаба: контроллер, чей owner = этот префаб
    - name: anim
      source: {path: extra/anim_clips.csv, format: csv}
      right: "owner_prefabs | split:; | stem | lower"
      on: "$id | lower"
      match: contains_right
      where: "contains(owner_prefabs, '/playerskills/')"
      columns:
        anim_len_max_s: {field: effective_length_s, agg: max}
        anim_states:    {agg: count}
    # тир арканы (в коде: LootManager.skillTierDict)
    - name: tier
      source: {format: csharp_dict, file: LootManager.cs, symbol: skillTierDict, resolve: staticID}
      right: "id | lower"
      on: "$id | lower"
      match: exact
      columns:
        arcana_tier: {field: group, agg: first}

# ------------------------------------------------------------------ скиллы врагов (сырьё для enemies/bosses)
- id: enemy_skills
  kind: enemy_skill
  source: {path: text/assets/data/enemy/skills.json, format: json, root: skillStats}
  key: "ID[0]"
  columns:
    element:           {path: "elementType[0]", type: enum}
    targets:           {path: "targetNames", array: join, type: enum}
    damage:            "damage[0]"
    knockback:         "knockbackMultiplier[0]"
    hitstun_mult:      "hitStunDurationModifier[0]"
    same_attack_immunity_s: "sameAttackImmunityTime[0]"
    same_target_immunity_s: "sameTargetImmunityTime[0]"
    crit_chance:       "criticalHitChance[0]"
    crit_damage_mult:  "criticalDamageModifier[0]"
    burn_chance:       "burnChance[0]"
    freeze_chance:     "freezeChance[0]"
    freeze_duration_s: "freezeDuration[0]"
    shock_chance:      "shockChance[0]"
    slow_chance:       "slowChance[0]"
    poison_chance:     "poisonChance[0]"
    duration_s:        "duration[0]"

# ------------------------------------------------------------------ враги
# статы из префаба + скиллы (по префиксу id) + хитбокс + длины анимаций
- id: enemies
  kind: enemy
  source: {glob: "prefabs/assets/prefabs/enemies/*.json", format: json_file}
  key: "$stem"
  columns:
    max_health:        {path: "objects[0].components[?class==Health].fields.healthStat", array: first}
    armor:             {path: "objects[0].components[?class==Health].fields.armorStat"}
    evade:             {path: "objects[0].components[?class==Health].fields.evadeStat"}
    damage_taken_mult: {path: "objects[0].components[?class==Health].fields.damageTakenStat"}
    move_speed:        {path: "objects[0].components[?class==Movement].fields.moveSpeedStat"}
    dash_speed:        {path: "objects[0].components[?class==Movement].fields.dashSpeedStat"}
    dash_duration_s:   {path: "objects[0].components[?class==Movement].fields.dashDurationStat"}
    alert_radius:      {path: "objects[0].components[*].fields.alertRadius"}
    escape_radius:     {path: "objects[0].components[*].fields.escapeRadius"}
    attack_radius:     {path: "objects[0].components[*].fields.attackRadius"}
    surround_radius:   {path: "objects[0].components[*].fields.surroundRadius"}
    alert_nearby_radius: {path: "objects[0].components[*].fields.alertNearbyEnemiesRadius"}
    hitstun_mult:      {path: "objects[0].components[*].fields.hitStunDurationModifier"}
    element_id:        {path: "objects[0].components[*].fields.element", type: enum}
    mass:              {path: "objects[0].components[?class==Rigidbody2D].fields.m_Mass"}
    linear_drag:       {path: "objects[0].components[?class==Rigidbody2D].fields.m_LinearDrag"}
    n_components:      {path: "objects[0].components", array: len}
    ehp_vs_dps10:      {expr: "max_health / 10 if max_health != '' else ''"}
  joins:
    - name: skills
      source: {path: text/assets/data/enemy/skills.json, format: json, root: skillStats}
      right: "ID[0] | lower"
      on: ["$id", "neutral{$id}"]
      match: startswith_left
      columns:
        skill_count:     {agg: count}
        skill_dmg_max:   {field: "damage[0]", agg: max}
        skill_dmg_sum:   {field: "damage[0]", agg: sum}
        skill_kb_max:    {field: "knockbackMultiplier[0]", agg: max}
    - name: collider
      source: {path: extra/colliders.csv, format: csv}
      right: "prefab"
      on: "path"
      match: exact
      where: "endswith(gameobject, 'HurtBox') or endswith(gameobject, 'Hurtbox')"
      columns:
        hurtbox_w_m:     {field: world_size_x, agg: max}
        hurtbox_h_m:     {field: world_size_y, agg: max}
    - name: anim
      source: {path: extra/anim_clips.csv, format: csv}
      right: "owner_prefabs | split:;"
      on: "path"
      match: exact
      columns:
        anim_states:     {agg: count}
        longest_state_s: {field: effective_length_s, agg: max}
    - name: attack_anim
      source: {path: extra/anim_clips.csv, format: csv, where: "re('(?i)attack|windup|lunge|slam|slash|throw|cast|shoot|charge|spin|stab|fire|smash', state)"}
      right: "owner_prefabs | split:;"
      on: "path"
      match: exact
      columns:
        attack_states:      {agg: count}
        attack_anim_max_s:  {field: effective_length_s, agg: max}
        attack_anim_min_s:  {field: effective_length_s, agg: min}

# ------------------------------------------------------------------ боссы
- id: bosses
  kind: boss
  source: {glob: "prefabs/assets/prefabs/bosses/*.json", format: json_file}
  key: "$stem"
  columns:
    max_health:        {path: "objects[0].components[?class==Health].fields.healthStat"}
    armor:             {path: "objects[0].components[?class==Health].fields.armorStat"}
    evade:             {path: "objects[0].components[?class==Health].fields.evadeStat"}
    move_speed:        {path: "objects[0].components[?class==Movement].fields.moveSpeedStat"}
    dash_speed:        {path: "objects[0].components[?class==Movement].fields.dashSpeedStat"}
    dash_duration_s:   {path: "objects[0].components[?class==Movement].fields.dashDurationStat"}
    alert_radius:      {path: "objects[0].components[*].fields.alertRadius"}
    attack_radius:     {path: "objects[0].components[*].fields.attackRadius"}
    hitstun_mult:      {path: "objects[0].components[*].fields.hitStunDurationModifier"}
    element_id:        {path: "objects[0].components[*].fields.element", type: enum}
    mass:              {path: "objects[0].components[?class==Rigidbody2D].fields.m_Mass"}
  joins:
    - name: skills
      source: {path: text/assets/data/enemy/skills.json, format: json, root: skillStats}
      right: "ID[0] | lower"
      on: "$id"
      match: startswith_left
      columns:
        skill_count:     {agg: count}
        skill_dmg_max:   {field: "damage[0]", agg: max}
        skill_dmg_sum:   {field: "damage[0]", agg: sum}
    - name: anim
      source: {path: extra/anim_clips.csv, format: csv}
      right: "owner_prefabs | split:;"
      on: "path"
      match: exact
      columns:
        anim_states:     {agg: count}
        longest_state_s: {field: effective_length_s, agg: max}

# ------------------------------------------------------------------ реликвии: тиры и цены
# тир = ключ в LootManager.itemTierDict (код), базовая цена = storeprices.json, формулы цен - в consts
- id: relics
  kind: relic
  source: {format: csharp_dict, file: LootManager.cs, symbol: itemTierDict, resolve: staticID}
  key: "id"
  where: "resolved_flag == 1"
  columns:
    resolved_flag: {path: "resolved", type: int, hidden: true}
    tier:          {path: "group", type: int}
    pos_in_tier:   {path: "pos", type: int}
    base_price:    {const: 0, hidden: true}
  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first}
  # вычисляемые (после join'ов)
- id: relic_prices
  kind: relic_price
  source: {format: csharp_dict, file: LootManager.cs, symbol: itemTierDict, resolve: staticID}
  key: "id"
  where: "resolved_flag == 1"
  columns:
    resolved_flag: {path: "resolved", type: int, hidden: true}
    tier:          {path: "group", type: int}
  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first, type: int, hidden: true}
  # цены считаются отдельными колонками ниже
  # (expr-колонки вычисляются после join'ов независимо от порядка в YAML)
  # base = listed_price или default_base_price (нет в словаре -> 1)
  # gold = base * 25; plat = base + (tier + 1) * 4
  # NB: expr-колонки перечислены в `columns`; для ясности вынесены в отдельный блок ниже.

# ------------------------------------------------------------------ арканы: тиры и цены
- id: arcana_tiers
  kind: arcana_tier
  source: {format: csharp_dict, file: LootManager.cs, symbol: skillTierDict, resolve: staticID}
  key: "id"
  where: "resolved_flag == 1"
  columns:
    resolved_flag: {path: "resolved", type: int, hidden: true}
    tier:          {path: "group", type: int}
  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first, type: int, hidden: true}

# ------------------------------------------------------------------ цены магазина (сырые)
- id: store_prices
  kind: store_price
  source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
  key: "name"
  columns:
    base_price:  {path: "price", type: int}
    gold_price:  {expr: "base_price * gold_price_mult", type: int}
  joins:
    - name: itier
      source: {format: csharp_dict, file: LootManager.cs, symbol: itemTierDict, resolve: staticID}
      right: "id"
      on: "$id"
      match: exact
      columns:
        relic_tier: {field: group, agg: first, type: int}
    - name: stier
      source: {format: csharp_dict, file: LootManager.cs, symbol: skillTierDict, resolve: staticID}
      right: "id"
      on: "$id"
      match: exact
      columns:
        arcana_tier: {field: group, agg: first, type: int}

# ------------------------------------------------------------------ комнаты
- id: rooms
  kind: room
  source: {path: text/assets/data/rooms/roomdb.json, format: json_delimited, separator: "!=-=!"}
  key: "name"
  columns:
    type_id:        {path: type, type: int}
    width:          {path: width, type: int}
    height:         {path: height, type: int}
    area:           {expr: "width * height", type: int}
    element_id:     {path: element, type: int}
    optional_conn_mask: {path: optionalConnections, type: int}
    required_conn_mask: {path: requiredConnections, type: int}
  joins:
    - name: prefab
      source: {path: prefabs/_index.csv, format: csv, where: "contains(path, '/rooms/prefabs/')"}
      right: "path | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        prefab_objects:    {field: n_objects, agg: first, type: int}
        prefab_components: {field: n_components, agg: first, type: int}
    - name: colliders
      source: {path: extra/colliders.csv, format: csv, where: "contains(prefab, '/rooms/prefabs/')"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        n_colliders:      {agg: count}
        n_trigger_colliders: {field: is_trigger, agg: sum}
    - name: lights
      source: {path: extra/lights.csv, format: csv, where: "contains(prefab, '/rooms/prefabs/')"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        n_lights: {agg: count}
    - name: ui
      source: {path: extra/ui_elements.csv, format: csv, where: "contains(prefab, '/rooms/prefabs/')"}
      right: "prefab | stem | lower"
      on: "$id | lower"
      match: exact
      columns:
        n_ui_elements: {agg: count}

# ------------------------------------------------------------------ дроп-таблицы (числа)
- id: loot_tables
  kind: loot_table
  source: {path: text/assets/data/loot/loottable.json, format: json, root: dropTableEntries}
  key: "name"
  columns:
    min_soul: {path: minSoul}
    max_soul: {path: maxSoul}
    gold_rate: {path: goldDropRate}
    min_gold: {path: minGold}
    max_gold: {path: maxGold}
    plat_rate: {path: platDropRate}
    min_plat: {path: minPlat}
    max_plat: {path: maxPlat}
    health_rate: {path: healthDropRate}
    min_health: {path: minHealth}
    max_health: {path: maxHealth}
    item_rate: {path: itemDropRate}
    skill_rate: {path: skillDropRate}
    locked_skill_rate: {path: lockedSkillDropRate}
    signature_skill_rate: {path: signatureSkillDropRate}
    n_item_drop_list: {path: itemDropList, array: len}
    n_skill_drop_list: {path: skillDropList, array: len}

# ------------------------------------------------------------------ кривые значений (value_curves)
- id: curves
  kind: curve
  records: per_catalog
  md_max_rows: 1500
  source: {path: extra/curves.json, format: json, root: curves}
  key: "{owner | stem}#{go}{clip}#{field}"
  columns:
    source_kind:  {path: source, type: enum}
    target_path:  {path: target_path, type: id}
    target_type:  {path: target_type, type: enum}
    n_keys:       {path: keys, array: len}
    t_end_s:      {path: "keys[-1][0]"}
    v_first:      {path: "keys[0][1]"}
    v_last:       {path: "keys[-1][1]"}
    v_min:        {path: "keys[*][1]", array: min}
    v_max:        {path: "keys[*][1]", array: max}
    pre_wrap:     {path: preWrap, type: int}
    post_wrap:    {path: postWrap, type: int}
- id: curves_by_owner
  kind: curve_owner
  source: {path: extra/curves.json, format: json, root: curves}
  key: "owner"
  columns:
    is_mono:      {const: 0, hidden: true}
  # агрегат по владельцу строится из каталога curves (ниже group), поэтому group задаётся на сырых строках
  group:
    by: [id]
    aggs:
      n_curves: {fn: count}

# ------------------------------------------------------------------ инвентарь ассетов (метаданные)
- id: asset_inventory
  kind: asset_inventory
  records: per_catalog
  md_max_rows: 2500
  source: {path: extra/asset_inventory_summary.csv, format: csv}
  key: "{group}::{type}"
  columns:
    group_path: {path: group, type: id}
    asset_type: {path: type, type: enum}
    count:      {path: count, type: int}
- id: asset_inventory_by_type
  kind: asset_type
  source: {path: extra/asset_inventory_summary.csv, format: csv, where: "group == '(all)'"}
  key: "type"
  columns:
    count:      {path: count, type: int}

# ------------------------------------------------------------------ новые коллекции (метаданные)
- id: vfx_emitters
  kind: vfx_emitter
  records: per_catalog
  source: {path: extra/vfx_particles.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    emitter_kind:    {path: kind, type: enum}
    duration_s:      {path: duration_s}
    looping:         {path: looping, type: bool}
    start_lifetime_s: {path: start_lifetime}
    start_speed:     {path: start_speed}
    start_size:      {path: start_size}
    gravity:         {path: gravity_modifier}
    max_particles:   {path: max_particles, type: int}
    rate_per_s:      {path: emission_rate}
    burst_total_min: {path: burst_total_min, type: int}
    shape_type:      {path: shape_type, type: enum}
    shape_radius:    {path: shape_radius}
    modules:         {path: modules_enabled, type: enum}
    sort_order:      {path: sort_order, type: int}
    est_particles_per_cycle: {expr: "burst_total_min + (rate_per_s * duration_s if rate_per_s != '' and duration_s != '' else 0)"}

- id: lights
  kind: light
  records: per_catalog
  source: {path: extra/lights.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    light_type_id: {path: light_type, type: enum}
    color_r: {path: color_r}
    color_g: {path: color_g}
    color_b: {path: color_b}
    intensity: {path: intensity}
    range_m: {path: range}
    spot_angle: {path: spot_angle}
    shadows_id: {path: shadows, type: enum}
    has_animator: {path: has_animator, type: bool}

- id: audio_clips
  kind: audio_clip
  records: per_catalog
  source: {path: extra/audio_clips.csv, format: csv}
  key: "container_path | stem"
  columns:
    group_path: {path: group, type: id}
    length_s:   {path: length_s}
    frequency_hz: {path: frequency, type: int}
    channels:   {path: channels, type: int}
    bits:       {path: bits, type: int}
    load_type_id: {path: load_type, type: enum}
    compression_id: {path: compression, type: enum}

- id: ui_canvases
  kind: ui_canvas
  source: {path: extra/ui_canvases.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    render_mode: {path: render_mode, type: enum}
    sort_order: {path: sort_order, type: int}
    plane_distance: {path: plane_distance}
    ref_res_x: {path: ref_res_x}
    ref_res_y: {path: ref_res_y}
    ref_ppu: {path: ref_ppu}

- id: ui_elements
  kind: ui_element
  records: per_catalog
  md_max_rows: 1500
  source: {path: extra/ui_elements.csv, format: csv}
  key: "{prefab | stem}/{go}"
  columns:
    kinds: {path: kinds, type: enum}
    depth: {path: depth, type: int}
    anchor_min_x: {path: anchor_min_x}
    anchor_min_y: {path: anchor_min_y}
    anchor_max_x: {path: anchor_max_x}
    anchor_max_y: {path: anchor_max_y}
    size_x: {path: size_x}
    size_y: {path: size_y}
    pos_x: {path: pos_x}
    pos_y: {path: pos_y}
    n_children: {path: n_children, type: int}

- id: input_actions
  kind: input_action
  source: {path: extra/input_actions.csv, format: csv}
  key: "name"
  columns:
    action_id: {path: action_id, type: int}
    type_id:   {path: type, type: enum}
    user_assignable: {path: user_assignable, type: bool}
  joins:
    - name: bindings
      source: {path: extra/input_default_bindings.csv, format: csv}
      right: "action_name"
      on: "$id"
      match: exact
      columns:
        n_default_bindings: {agg: count}

- id: input_default_bindings
  kind: input_binding
  source: {path: extra/input_default_bindings.csv, format: csv}
  key: "{map_kind}/{action_name}/{element_type}-{element_identifier_id}-{key_code}-{axis_contribution}"
  columns:
    map_kind_id:  {path: map_kind, type: enum}
    element_type: {path: element_type, type: enum}
    element_identifier_id: {path: element_identifier_id, type: int}
    axis_range:   {path: axis_range, type: enum}
    axis_contribution: {path: axis_contribution, type: enum}
    key_code:     {path: key_code, type: int}

- id: tilesets
  kind: tileset
  source: {path: extra/tiled_tilesets.csv, format: csv}
  key: "name"
  columns:
    tile_w: {path: tile_w, type: int}
    tile_h: {path: tile_h, type: int}
    image_w: {path: image_w, type: int}
    image_h: {path: image_h, type: int}
    columns: {path: columns, type: int}
    tile_count: {path: tile_count, type: int}

- id: tilemaps
  kind: tilemap
  records: per_catalog
  source: {path: extra/tiled_maps.csv, format: csv}
  key: "path | stem"
  columns:
    width: {path: width, type: int}
    height: {path: height, type: int}
    n_layers: {path: n_layers, type: int}
    n_tilesets: {path: n_tilesets, type: int}
    n_nonempty_tiles: {path: n_nonempty_tiles, type: int}
    fill_ratio: {expr: "n_nonempty_tiles / (width * height * n_layers) if width and height and n_layers else ''"}

- id: decor_variants
  kind: decor_variant
  records: per_catalog
  md_max_rows: 1500
  source: {path: extra/decor_variants.csv, format: csv}
  key: "{prefab | stem}/{go}/{field}"
  columns:
    decor_class: {path: class, type: enum}
    n_items: {path: n_items, type: int}
    n_distinct: {path: n_distinct, type: int}

