  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first, type: int, hidden: true}

# ------------------------------------------------------------------ арканы: тиры и цены
- id: arcana_tiers
  kind: arcana_tier
  source: {format: csharp_dict, file: LootManager.cs, symbol: skillTierDict, resolve: staticID}
  key: "id"
  where: "resolved_flag == 1"
  columns:
    resolved_flag: {path: "resolved", type: int, hidden: true}
    tier:          {path: "group", type: int}
    pos_in_tier:   {path: "pos", type: int}
    base_price:    {expr: "listed_price if listed_price != '' else default_base_price", type: int}
    gold_price:    {expr: "base_price * gold_price_mult", type: int}
    plat_price:    {expr: "base_price + clamp(tier, 1, 4) * arcana_plat_tier_mult", type: int}
  joins:
    - name: price
      source: {path: text/assets/data/loot/storeprices.json, format: json, root: storePrices}
      right: "name"
      on: "$id"
      match: exact
      columns:
        listed_price: {field: price, agg: first, type: int, hidden: true}

'''
s=s[:a]+new+s[b:]
a=s.index("- id: curves_by_owner")
b=s.index("# ------------------------------------------------------------------ инвентарь ассетов")
new='''- id: curves_by_owner
  kind: curve_owner
  source: {path: extra/curves.json, format: json, root: curves}
  key: "{owner}#{go}{clip}#{field}#{target_path}"
  columns:
    owner_path: {path: owner, type: id}
    n_keys:     {path: keys, array: len}
  group:
    by: [owner_path]
    aggs:
      n_curves:   {fn: count}
      total_keys: {fn: sum, field: n_keys}
      max_keys:   {fn: max, field: n_keys}

'''
s=s[:a]+new+s[b:]
open("wol.yaml","w",encoding="utf-8",newline="\n").write(s)
E
